
const LK_DATABASE = {"lk1": {"title": "LEMBAR KERJA 1 (LK 1) — IDENTIFIKASI DIRI", "filename": "LK 1 _ Seminar PPG _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK 1 _ Seminar PPG _ A. Wahyu Redhani _ 2530111713968.pdf", "docx": "", "rows": [{"indikator": "Visi pribadi untuk pendidikan di Indonesia", "pertanyaan": "Apa visi saya untuk pendidikan di Indonesia?", "jawaban": "Visi pribadi saya untuk pendidikan di Indonesia adalah terwujudnya lingkungan belajar yang merata, ramah, dan peduli pada setiap anak. Saya memimpikan pendidikan di mana setiap anak dari berbagai pelosok mendapatkan kesempatan yang sama untuk belajar dan berkembang tanpa merasa dibeda-bedakan. Saya berharap sekolah tidak hanya sekadar tempat mengejar nilai rapor, tapi juga menjadi tempat anak-anak belajar peduli sesama, berpikir kritis, dan mengenali potensi dirinya sendiri agar mereka siap menghadapi kehidupan nyata di masyarakat."}, {"indikator": "Visi pribadi sebagai calon guru", "pertanyaan": "Apa visi saya sebagai calon guru?", "jawaban": "Sebagai calon guru, visi saya adalah menjadi teman belajar sekaligus pembimbing yang sabar dan tulus bagi murid-murid saya. Saya tidak hanya ingin masuk kelas sekadar untuk menghabiskan materi buku, tapi saya ingin hadir untuk memahami karakter dan cara belajar mereka yang pasti berbeda-beda. Saya bervisi menjadi guru yang bisa menumbuhkan rasa percaya diri anak, dan selalu meyakinkan mereka bahwa setiap usaha dan keberanian mereka untuk mencoba adalah hal yang sangat berharga."}, {"indikator": "Hal yang dilakukan untuk mencapai visi", "pertanyaan": "Apa yang akan saya lakukan untuk mencapai visi tersebut?", "jawaban": "1. Terus belajar dan memperbaiki diri: Saya sadar bahwa untuk mendidik murid dengan baik, saya sendiri tidak boleh berhenti belajar. Saya akan membiasakan diri untuk merenung dan mengevaluasi cara mengajar saya setiap selesai kelas. Saya juga akan lebih rajin berdiskusi dengan sesama rekan guru, guru pamong, maupun dosen pembimbing untuk meminta saran dan masukan.\n2. Menciptakan pelajaran yang menyenangkan dan dekat dengan keseharian anak: Saya sadar tiap anak punya minat yang berbeda. Oleh karena itu, saya akan merancang suasana kelas yang tidak membosankan dan materinya mudah dipahami karena terhubung dengan kehidupan mereka sehari-hari. Saya akan mengurangi kebiasaan ceramah terus-menerus dan lebih banyak mengajak murid untuk berdiskusi, bekerja sama, dan mencoba hal-hal baru secara langsung.\n3. Membangun ruang kelas yang menghargai proses: Saya ingin kelas saya menjadi tempat yang aman bagi anak-anak untuk berani mencoba dan tidak takut dimarahi ketika berbuat salah saat belajar. Saya akan lebih banyak menghargai keringat, usaha, dan kegigihan mereka, bukan sekadar melihat hasil nilai akhirnya saja. Dengan begitu, saya harap mereka bisa tumbuh menjadi anak yang pantang menyerah."}, {"indikator": "Kesimpulan", "pertanyaan": "Refleksi Komitmen PPG", "jawaban": "Mengikuti program Pendidikan Profesi Guru (PPG) ini bagi saya bukan sekadar formalitas untuk mencari sertifikat pendidik, melainkan langkah nyata untuk memantaskan diri. Semua niat dan rencana di atas adalah wujud kesungguhan saya untuk membawa perubahan yang positif. Saya yakin, perubahan besar untuk pendidikan Indonesia yang lebih baik selalu dimulai dari kasih sayang dan langkah-langkah kecil yang dilakukan seorang guru di dalam ruang kelasnya setiap hari."}]}, "lk3": {"title": "LEMBAR KERJA 3 (LK 3) — REFLEKSI PENGALAMAN BELAJAR SELAMA MENGIKUTI PPG", "filename": "LK Refleksi Pengalaman Belajar PPG _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Pengalaman Belajar PPG _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar selama mengikuti Program PPG", "pertanyaan": "Setelah mengikuti rangkaian refleksi pengalaman belajar, menurut anda, bagaimana seharusnya pendidikan di Indonesia?", "jawaban": "Berdasarkan refleksi mendalam terhadap seluruh rangkaian perkuliahan teoritis dan pengalaman praktik nyata mengajar murid kelas X-B DKV dan X-C DKV di SMKN 1 Banjarmasin, pandangan saya mengenai arah pendidikan nasional mengalami transformasi yang sangat mendasar. Menurut saya, pendidikan di Indonesia seharusnya berlandaskan pada prinsip-prinsip luhur berikut:\n1. Pendidikan yang Hakiki Harus Menuntun dan Berpihak pada Murid\nPendidikan tidak boleh lagi diposisikan sebagai proses pembentukan seragam atau pemaksaan standar mekanis yang kaku. Mengadopsi filosofi Ki Hadjar Dewantara, pendidikan sejatinya adalah proses 'menuntun segala kodrat yang ada pada anak', baik kodrat alam (latar sosiokultural, potensi unik, minat, dan bakat) maupun kodrat zaman (tuntutan era kecerdasan buatan dan dinamika digital global). Di kelas kejuruan SMK, saya menyaksikan betapa berharganya ruang kebebasan berkarya bagi anak DKV yang visual dan ekspresif. Ketika pendidikan memfasilitasi kodrat tersebut, murid tidak belajar karena terpaksa, melainkan bertumbuh dengan kesadaran diri yang merdeka.\n2. Menggeser Orientasi dari Angka Semata Menuju Pengembangan Manusia Utuh (Holistik)\nPraktik pendidikan di tanah air terlalu lama terperangkap dalam fetisisme nilai kognitif dan ketuntasan administratif kurikulum. Pendidikan yang bermutu idealnya mengembangkan seluruh dimensi kemanusiaan: olah cipta (penalaran kritis dan komputasional), olah rasa (kehalusan budi pekerti dan empati sosial), olah karsa (ketahanan mental dan inisiatif), serta olah raga (kesehatan fisik dan integritas karya). Pembelajaran Informatika, misalnya, tidak boleh hanya mencetak operator perangkat lunak yang andal secara teknis, tetapi gagal menghasilkan pribadi yang memiliki etika digital, kejujuran intelektual, dan kepedulian terhadap privasi sesama.\n3. Mewujudkan Pembelajaran Mendalam (Deep Learning) yang Berkesadaran, Bermakna, dan Menggembirakan (3B)\nPendidikan harus membebaskan murid dari belenggu hafalan rumus instan (surface learning). Pembelajaran harus dikonstruksi secara mendalam melalui keterhubungan konsep dengan realitas kehidupan sehari-hari murid. Belajar harus menjadi peristiwa yang Berkesadaran (Mindful, hadir utuh dalam proses), Bermakna (Meaningful, tahu manfaat ilmu bagi diri dan masyarakat), serta Menggembirakan (Joyful, antusias memecahkan tantangan). Pembelajaran komputasi di SMK menjadi hidup ketika murid mengolah data nyata kearifan lokal Kalimantan Selatan (seperti data hidrologi Waduk Riam Kanan), bukan sekadar mengetik ulang angka fiktif yang kering.\n4. Pendidikan yang Berkeadilan, Inklusif, dan Tanggap Keberagaman (TaRL & DUP)\nSekolah harus menjadi ruang aman yang merangkul keberagaman tingkat kesiapan belajar, gaya belajar, dan kondisi sosioekonomi keluarga. Melalui pendekatan Teaching at the Right Level (TaRL) dan Desain Universal untuk Pembelajaran (DUP), guru melayani setiap anak sesuai titik capaian aktualnya. Tidak boleh ada lagi vonis 'murid bodoh' hanya karena ia membutuhkan tempo belajar dan jenis bantuan (scaffolding) yang berbeda dari teman-temannya di laboratorium komputer.\n5. Menciptakan Ekosistem Sekolah yang Ramah, Aman, dan Menguatkan Kesejahteraan (School Well-Being)\nPendidikan hanya akan efektif apabila ruang kelas dan laboratorium sekolah terbebas dari rasa takut, diskriminasi, perundungan siber (cyberbullying), dan ancaman hukuman destruktif. Integrasi Pembelajaran Sosial Emosional (PSE) mutlak diperlukan agar guru dan murid mampu menjalin relasi hangat, saling menguatkan dengan pola pikir bertumbuh (growth mindset), dan menjadikan sekolah sebagai rumah kedua yang memanusiakan manusia."}, {"indikator": "Refleksi pengalaman belajar selama mengikuti Program PPG", "pertanyaan": "Apa saja yang dapat anda lakukan untuk menjadi guru profesional?", "jawaban": "Menjadi guru profesional bukanlah sebuah gelar administratif atau status statis setelah mengantongi sertifikat pendidik, melainkan ikrar komitmen berkelanjutan untuk terus mengasah empat kompetensi guru secara terintegrasi dalam tindakan nyata sehari-hari:\n1. Memperkokoh Kompetensi Pedagogik Melalui Perancangan Pembelajaran Adaptif\nSaya berkomitmen untuk selalu menerapkan kerangka kerja Understanding by Design (UbD / Backward Design) dalam merumuskan tujuan pembelajaran, asesmen autentik, dan alur aktivitas. Saya akan secara disiplin mengawali setiap bab pembelajaran dengan Asesmen Diagnostik Awal untuk memetakan kesiapan murid, sehingga strategi diferensiasi (konten, proses, produk) dan pendekatan TaRL dapat diimplementasikan secara terukur dan adil bagi seluruh murid di kelas kejuruan.\n2. Memperbarui Kompetensi Profesional Bidang Informatika Berkelanjutan\nIlmu Informatika bergerak dengan kecepatan eksponensial. Sebagai guru SMK, saya berkewajiban terus memperbarui keilmuan saya, mempelajari perkembangan kecerdasan buatan (AI), analisis data, keamanan siber, dan rekayasa perangkat lunak, serta menyelaraskan materi pembelajaran dengan standar kebutuhan Dunia Usaha dan Dunia Industri (DUDI). Saya tidak boleh berhenti belajar dan tertinggal oleh kemajuan teknologi yang digunakan murid di luar sekolah.\n3. Mengembangkan Kompetensi Kepribadian sebagai Teladan (Ing Ngarso Sung Tulodo)\nSaya akan senantiasa menampilkan keteladanan moral, etika digital, kesabaran, dan integritas tinggi. Di ruang kelas dan laboratorium komputer, saya berkomitmen menunjukkan keteladanan dalam menghormati hak kekayaan intelektual (tidak menggunakan peranti lunak bajakan), bertutur kata yang menumbuhkan pola pikir bertumbuh (process praise), serta mengendalikan emosi secara matang saat menghadapi situasi kelas yang menantang.\n4. Memperkuat Kompetensi Sosial dan Kemitraan Komunitas\nSaya akan membangun komunikasi yang hangat, empatik, dan transparan dengan murid, orang tua/wali, rekan sejawat, dan manajemen sekolah. Saya akan aktif menggerakkan Komunitas Belajar (Kombel) di sekolah dan Musyawarah Guru Mata Pelajaran (MGMP) Informatika SMK untuk saling berbagi praktik baik (best practice) dan melakukan Lesson Study kolaboratif.\n5. Menjadi Praktisi yang Reflektif (Reflective Practitioner) Sepanjang Hayat\nSaya akan membiasakan diri menulis jurnal refleksi harian pasca-pembelajaran, mengevaluasi efektivitas metode yang digunakan, serta terbuka terhadap kritik konstruktif. Saya juga akan konsisten melaksanakan Penelitian Tindakan Kelas (PTK) guna menguji solusi ilmiah atas problematika nyata pembelajaran di laboratorium komputer.\n6. Mengembangkan Inovasi Pembelajaran Digital yang Berdaya Guna\nSaya akan terus mendesain dan menyempurnakan media pembelajaran interaktif berbasis web (seperti platform Informatika Learning Hub) guna memfasilitasi kemandirian belajar murid di era digital secara inklusif dan menyenangkan."}, {"indikator": "Rencana Tindak Lanjut", "pertanyaan": "Apa saja tiga hal penting yang akan anda lakukan ketika memulai karir sebagai guru?", "jawaban": "Ketika memulai karier sebagai guru profesional seutuhnya pasca-kelulusan Program PPG Informatika, saya menetapkan tiga rencana tindak lanjut strategis, realistis, dan terukur yang akan saya eksekusi secara konsisten:\n1. Meningkatkan Kualitas Perencanaan dan Pelaksanaan Pembelajaran Berorientasi Murid\nSaya akan membiasakan diri menyusun perangkat pembelajaran (Modul Ajar, Bahan Ajar, LKPD, dan Asesmen) yang berbasis pada kerangka Understanding by Design (UbD). Perencanaan pembelajaran tidak akan lagi didasarkan pada perkiraan sepihak guru, melainkan selalu diawali dengan Asesmen Diagnostik Kognitif dan Non-Kognitif pada awal semester dan awal bab. Berdasarkan data pemetaan tersebut, saya akan menerapkan pembelajaran berdiferensiasi dan pendekatan Teaching at the Right Level (TaRL) secara konsisten, sehingga setiap murid, baik kategori Perintis yang memerlukan bantuan intensif (scaffolding), kategori Cakap, maupun kategori Mahir, mendapatkan perlakuan pedagogik yang tepat dan bermakna di laboratorium komputer.\n2. Mengembangkan Pembelajaran Informatika yang Aktif, Kontekstual, dan Berbasis Inovasi Media Digital\nSaya akan mentransformasi proses belajar-mengajar di kelas kejuruan dari metode ceramah pasif menjadi pembelajaran aktif melalui model Project-Based Learning (PjBL) dan Problem-Based Learning (PBL). Saya akan menghubungkan konsep-konsep Informatika (seperti literasi digital, analisis data, dan logika pemrograman) dengan isu kontekstual kearifan lokal Kalimantan Selatan dan kebutuhan riil industri kreatif kejuruan. Selain itu, saya akan mengimplementasikan dan mengembangkan media digital mandiri, seperti website pembelajaran interaktif Informatika Learning Hub, yang mengintegrasikan materi terstruktur, video tutorial demonstratif, latihan kuis adaptif, dan elemen gamifikasi yang memotivasi murid belajar secara mandiri, fleksibel, dan terarah kapan pun dan di mana pun.\n3. Melakukan Refleksi Berkelanjutan dan Pengembangan Kompetensi Profesional Sepanjang Hayat\nSaya akan melembagakan budaya refleksi diri dengan rutin menulis jurnal refleksi harian pasca-mengajar guna menganalisis aspek pembelajaran yang berhasil dan area teknis yang memerlukan perbaikan. Saya akan membuka diri untuk dievaluasi oleh rekan sejawat dan kepala sekolah melalui kegiatan supervisi klinis dan Lesson Study berkala. Selain itu, saya berkomitmen aktif berkontribusi dalam Komunitas Belajar (MGMP Informatika SMK), mengikuti pelatihan keprofesian berkelanjutan (khususnya perkembangan teknologi kecerdasan buatan dan pedagogi mutakhir), serta melaksanakan Penelitian Tindakan Kelas (PTK) berbasis data asesmen murid secara periodik guna terus meningkatkan mutu pendidikan di sekolah penugasan."}]}, "lk4": {"title": "LEMBAR KERJA 4 (LK 4) — PENYUSUNAN DESAIN KARYA INOVATIF", "filename": "LK Desain Karya Inovatif _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Desain Karya Inovatif _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Identifikasi Kebutuhan dan Tantangan", "pertanyaan": "Bagaimana hasil amatan dan identifikasi terkait permasalahan atau kebutuhan atau tantangan yang ada dalam pembelajaran?", "jawaban": "Berdasarkan pengamatan faktual dan refleksi mendalam selama saya melaksanakan praktik mengajar Informatika di kelas X-B DKV dan X-C DKV SMKN 1 Banjarmasin, ditemukan sejumlah dinamika kebutuhan dan tantangan riil dalam pembelajaran:\n1. Fragmentasi Sumber Belajar Digital (Tantangan Akses Tersebar)\nDalam pembelajaran Informatika saat ini, materi pembelajaran sering kali terserak di berbagai platform yang tidak terintegrasi. Modul materi tersimpan dalam format PDF di Google Drive atau dibagikan melalui WhatsApp grup, video tutorial merujuk ke tautan YouTube eksternal, sedangkan lembar latihan menggunakan Google Forms terpisah atau kertas cetak. Fragmentasi ini menimbulkan friksi belajar (learning friction); murid harus berpindah-pindah aplikasi yang sering kali memakan kuota, memicu kebingungan urutan belajar, dan menurunkan kemandirian belajar murid di luar jam sekolah.\n2. Tingginya Distraksi Digital pada Platform Publik\nSaat murid diarahkan menonton video pembelajaran di platform publik seperti YouTube, algoritma rekomendasi video hiburan dan tayangan iklan komersial sangat mudah mengalihkan fokus perhatian murid. Di laboratorium komputer SMKN 1 Banjarmasin, murid kelas X DKV yang memiliki rasa ingin tahu visual tinggi sering kali terdistraksi membuka tab video musik atau game online ketimbang menyimak substansi materi pelajaran.\n3. Kebutuhan Media Belajar Terpadu yang Ringan dan Responsif\nKarakteristik murid kejuruan DKV menunjukkan preferensi belajar yang sangat visual, aplikatif, dan menyukai antarmuka yang bersih. Di sisi lain, terdapat kesenjangan kepemilikan perangkat di rumah: tidak semua murid memiliki komputer pribadi (PC/laptop), sehingga media pembelajaran digital yang dirancang harus ramah terhadap peramban telepon pintar (mobile-friendly) dengan beban akses yang ringan dan menggunakan bahasa Indonesia yang lugas dan komunikatif.\n4. Kebutuhan Umpan Balik Cepat (Immediate Feedback) pada Latihan Formatif\nPada praktik konvensional, murid mengerjakan lembar kerja praktikum dan baru mengetahui kesalahannya beberapa hari atau minggu kemudian setelah guru selesai mengoreksi secara manual. Jeda waktu yang panjang ini menghilangkan momen emas belajar (teachable moment). Murid membutuhkan sistem latihan interaktif yang mampu memberikan skor langsung dan pembahasan singkat seketika setelah soal selesai dikerjakan.\n5. Pentingnya Unsur Motivasi dan Gamifikasi yang Sehat\nPembelajaran materi teoritis Informatika (seperti konsep data, representasi informasi, dan validasi logika) kerap dianggap menjemukan bagi murid kejuruan jika hanya disajikan dalam bentuk teks naratif panjang. Diperlukan elemen permainan (gamification) berupa perolehan skor dan papan peringkat (leaderboard) untuk memantik gairah kompetisi yang positif, tanpa mengabaikan penghargaan terhadap proses belajar individu."}, {"indikator": "Perumusan gagasan dan tujuan inovasi", "pertanyaan": "Berdasarkan identifikasi di atas, bagaimana gagasan kreatif untuk mengembangkan solusi inovatif?", "jawaban": "Sebagai respon terukur atas hasil identifikasi kebutuhan di atas, saya merumuskan gagasan kreatif untuk mengembangkan media pembelajaran digital mandiri berbasis web bernama:\n'Informatika Learning Hub – Website Pembelajaran Interaktif Informatika'\nGagasan utama dari karya inovatif ini adalah menghadirkan sebuah platform web edukasi satu pintu (all-in-one learning platform) berbahasa Indonesia sepenuhnya yang mengintegrasikan seluruh siklus belajar murid ke dalam satu antarmuka yang ringkas, modern, dan intuitif.\nUntuk tahap percontohan dan prototipe awal, website ini difokuskan pada materi esensial Kurikulum Merdeka Fase E:\nBab: Data, Informasi, dan Validasi (Elemen Analisis Data / Literasi Digital).\nWebsite ini dirancang secara modular dan memadukan Empat Fitur Utama yang saling terhubung secara harmonis:\n1. Fitur Materi Pembelajaran Terstruktur: Menyajikan pemaparan konsep esensial mengenai hakikat data mentah, proses transformasi menjadi informasi yang bermakna, serta teknik validasi keabsahan data digital. Disajikan dengan bahasa Indonesia yang komunikatif, dilengkapi bagan alur, infografis visual menarik khas anak DKV, dan contoh studi kasus nyata.\n2. Fitur Video Pembelajaran Terkurasi: Menyematkan video pembelajaran ringkas (durasi 5–7 menit) yang fokus memvisualisasikan konsep abstrak dan demonstrasi praktikum validasi data tanpa gangguan iklan luar.\n3. Fitur Kuis dan Asesmen Interaktif: Menyediakan latihan soal formatif adaptif pilihan ganda. Sistem secara otomatis menghitung skor murid seketika (instant scoring) dan memberikan ulasan jawaban yang benar sebagai sarana penguatan konsep (reinforcement).\n4. Fitur Leaderboard (Papan Peringkat Interaktif): Menampilkan urutan peringkat perolehan skor kuis murid secara real-time untuk membangun iklim kompetisi belajar yang sehat, menyenangkan, dan memotivasi murid mengulang latihan jika belum mencapai pemahaman maksimal."}, {"indikator": "Perumusan gagasan dan tujuan inovasi", "pertanyaan": "Bagaimana rumusan tujuan dari gagasan atau solusi inovasi tersebut?", "jawaban": "Gagasan pengembangan website 'Informatika Learning Hub' dirumuskan dengan tujuan-tujuan konkret sebagai berikut:\n1. Mempermudah Aksesibilitas dan Sentralisasi Sumber Belajar Mandiri\nMenyediakan repositori digital terpusat yang dapat diakses oleh murid SMK secara fleksibel kapan saja dan di mana saja, baik melalui komputer laboratorium sekolah maupun telepon pintar (smartphone) pribadi dengan beban kuota minimal.\n2. Meningkatkan Pemahaman Konseptual Melalui Penguatan Audiovisual Terfokus\nMenyediakan video pembelajaran ringkas yang bebas dari distraksi iklan platform publik, membantu murid memvisualisasikan perbedaan konseptual antara data mentah, informasi terstruktur, dan prosedur validasi data secara nyata.\n3. Memfasilitasi Asesmen Formatif Mandiri dengan Umpan Balik Seketika\nMemungkinkan murid mengukur tingkat penguasaan materinya secara mandiri (self-assessment) melalui kuis interaktif yang memberikan umpan balik langsung, sehingga murid segera menyadari kekeliruan konsep yang dialaminya.\n4. Menumbuhkan Keterlibatan Aktif dan Motivasi Belajar Melalui Gamifikasi Positif\nMemanfaatkan fitur papan peringkat (leaderboard) untuk menciptakan atmosfer belajar yang menggembirakan (joyful learning), mendorong partisipasi aktif, serta merangsang daya juang murid untuk terus memperbaiki capaian belajarnya.\n5. Membantu Guru Memperoleh Data Pemahaman Murid Secara Cepat dan Presisi\nMenyediakan gambaran capaian formatif kelas secara cepat bagi guru berdasarkan rekapitulasi nilai kuis, sebagai dasar ilmiah untuk merancang program remedial bagi murid kelompok Perintis atau pengayaan bagi murid kelompok Mahir."}, {"indikator": "Perumusan gagasan dan tujuan inovasi", "pertanyaan": "Bagaimana kebaruan, kreativitas, relevansi, kebermanfaatan, dan keefektivitas produk inovasi yang telah dikembangkan?", "jawaban": "Analisis komprehensif terhadap lima dimensi prinsip karya inovasi pendidikan pada produk 'Informatika Learning Hub' adalah sebagai berikut:\n1. Kebaruan (Novelty)\nKebaruan karya ini bukan terletak pada klaim bahwa website ini adalah yang pertama di dunia, melainkan pada nilai tambah integrasi fungsionalnya (systemic integration). Selama ini, materi teks, video penjelasan, kuis formatif, dan papan peringkat biasanya berada di aplikasi terpisah (Drive, YouTube, Quizizz/Google Forms). Produk ini menyatukan keempat pilar tersebut ke dalam satu ekosistem web berbahasa Indonesia yang dirancang khusus selaras dengan Alur Tujuan Pembelajaran (ATP) Informatika Fase E SMK, berbobot ringan, serta bebas dari iklan komersial.\n2. Kreativitas\nKreativitas produk ini terwujud dalam perpaduan harmonis antara prinsip Deep Learning (Berkesadaran, Bermakna, Menggembirakan) dengan mekanika gamifikasi ringan. Konten materi disajikan dengan analogi visual yang lekat dengan dunia kreatif anak DKV, memadukan teks ringkas, media interaktif, dan validasi skor otomatis yang membangun pengalaman belajar yang mulus (seamless learning experience).\n3. Kebermanfaatan (Usefulness)\nKarya ini memberikan manfaat nyata bagi dua pihak: (a) Bagi murid: memberikan otonomi belajar mandiri (self-regulated learning) tanpa terhambat keterbatasan jam tatap muka di lab komputer; (b) Bagi guru: memangkas beban koreksi manual lembar latihan formatif, menyediakan bahan ajar yang rapi dan terstandarisasi, serta memudahkan pemantauan ketuntasan belajar murid.\n4. Relevansi dan Kontekstualitas\nSangat relevan dengan tuntutan Kurikulum Merdeka yang menekankan literasi digital, penalaran komputasional, dan kemandirian belajar peserta didik generasi Alpha/Z di SMK. Pemilihan materi 'Data, Informasi, dan Validasi' sangat kontekstual di era banjir informasi dan hoaks, melatih murid kejuruan agar mampu memilah fakta, mengevaluasi sumber data, dan memiliki integritas intelektual.\n5. Keefektivitasan (Evidence-Based)\nPotensi efektivitas produk ini diukur secara objektif dan bertahap. Melalui uji coba awal pada materi pengolahan data di kelas X-B DKV SMKN 1 Banjarmasin, integrasi bahan ajar terstruktur dan kuis formatif terbukti mampu mendongkrak ketuntasan belajar murid (seperti tercermin pada kenaikan nilai rata-rata asesmen dari 52.3 menjadi 83.3). Tingkat keefektifan produk akan terus divalidasi melalui uji fungsi sistem, angket kepuasan pengguna (System Usability Scale), dan perbandingan N-Gain secara berkala."}, {"indikator": "Riset dan pengembangan solusi", "pertanyaan": "Bagaimana hasil riset sederhana atau informasi karya-karya inovatif yang sudah ada terkait solusi inovatif?", "jawaban": "Pengembangan platform 'Informatika Learning Hub' dilandaskan pada tinjauan literatur ilmiah dan kajian empiris yang dapat diverifikasi secara akademik:\n1. Cognitive Theory of Multimedia Learning (Richard E. Mayer, 2001, 2009)\nRiset Mayer menegaskan bahwa manusia belajar lebih mendalam dari kata-kata dan gambar secara simultan daripada dari kata-kata saja (Multimedia Principle). Penataan materi yang memadukan teks terstruktur, infografis visual, dan video penjelasan ringkas dalam satu layar yang terorganisasi (Spatial Contiguity & Coherence Principle) terbukti secara ilmiah mampu meminimalkan beban kognitif berlebih (cognitive overload) dan mengoptimalkan memori kerja murid.\n2. Teori Gamifikasi dalam Pendidikan (Deterding et al., 2011; Karl Kapp, 2012)\nPenelitian tentang gamifikasi membuktikan bahwa penerapan elemen mekanika game non-game, seperti sistem perolehan poin (scoring) dan papan peringkat (leaderboard), mampu memicu motivasi intrinsik dan keterlibatan aktif (engagement) murid. Gamifikasi yang dirancang secara sehat memberikan dorongan pencapaian (need for competence) tanpa menciptakan kecemasan kompetisi yang destruktif.\n3. Web-Based Instruction & Self-Paced Learning (Khan, 1997; Clark & Mayer, 2016)\nRiset mengenai pengajaran berbasis web menunjukkan bahwa fleksibilitas platform digital memungkinkan murid belajar sesuai kecepatan masing-masing (self-paced). Murid kategori Perintis dapat mengulang video dan membaca materi berkali-kali tanpa merasa dihakimi, sementara murid kelompok Mahir dapat langsung menempuh kuis untuk membuktikan kompetensinya.\n4. Peran Formative Assessment & Immediate Feedback (Black & Wiliam, 1998; Hattie & Timperley, 2007)\nStudi metaanalisis John Hattie menunjukkan bahwa umpan balik yang diberikan seketika (immediate feedback) merupakan salah satu faktor dengan effect size tertinggi dalam mendongkrak prestasi belajar murid. Fitur kuis interaktif pada website ini mengadopsi prinsip tersebut guna mengonfirmasi pemahaman konsep seketika pasca-membaca."}, {"indikator": "Riset dan pengembangan solusi", "pertanyaan": "Bagaimana rancangan atau prototipe dari karya inovatif tersebut?", "jawaban": "Rancangan prototipe 'Informatika Learning Hub' dibangun dengan arsitektur web responsif yang sederhana, bersih, dan menggunakan standar teknologi web modern (HTML5, CSS3, dan Vanilla JavaScript) sehingga dapat dibuka dengan mulus pada peramban apa pun tanpa memerlukan instalasi aplikasi tambahan.\nA. Struktur Arsitektur Halaman Website:\n1. Halaman Beranda (Home Page): Menampilkan identitas website, capaian pembelajaran (CP) elemen yang dituju, peta navigasi menu yang jelas, serta salam pembuka yang ramah dan memotivasi murid.\n2. Halaman Materi (Content Page): Memuat materi terstruktur Bab 'Data, Informasi, dan Validasi'. Terbagi menjadi 3 sub-bab sistematis: (a) Pengertian & Perbedaan Mendasar Data vs Informasi; (b) Siklus Pengolahan Data Digital; dan (c) Prosedur & Kriteria Validasi Data (validasi tipe data, rentang nilai, format, dan konsistensi). Dilengkapi kotak sorotan (callout box) rangkuman dan studi kasus nyata.\n3. Halaman Video (Video Page): Pemutar video terintegrasi yang menyajikan video pembelajaran pendek fokus konsep dan demonstrasi praktikum validasi data menggunakan spreadsheet, disajikan dengan tata letak lebar dan kontrol navigasi intuitif.\n4. Halaman Kuis (Interactive Quiz Page): Antarmuka interaktif yang menyajikan paket soal formatif (10-15 butir pilihan ganda). Terdapat indikator kemajuan soal (progress bar), tombol pilihan jawaban interaktif, dan tombol kalkulasi hasil.\n5. Halaman Leaderboard (Leaderboard Page): Tabel dinamis yang menampilkan 10 peringkat teratas murid berdasarkan kecepatan dan ketepatan penyelesaian kuis, dilengkapi nama samaran (nickname) atau nama murid serta perolehan skor.\nB. Alur Penggunaan oleh Peserta Didik:\n1. Murid membuka tautan website melalui peramban komputer lab atau telepon pintar.\n2. Murid menyimak peta kompetensi di halaman Beranda, lalu memilih menu 'Materi'.\n3. Murid mempelajari pemaparan teks dan infografis, kemudian berpindah ke menu 'Video' untuk melihat demonstrasi praktikum kontekstual.\n4. Murid menguji pemahamannya secara mandiri di menu 'Kuis Interaktif'.\n5. Setelah menyelesaikan soal, sistem seketika memunculkan skor total, tanda benar/salah pada masing-masing butir, dan ulasan pembahasan singkat.\n6. Murid dapat melihat posisinya di papan peringkat 'Leaderboard', dan memiliki opsi mengulang kuis untuk memperbaiki pemahamannya.\nC. Peran Guru dalam Pemanfaatan Platform:\nGuru berperan sebagai fasilitator yang mengarahkan alur belajar, mendampingi murid yang mengalami kendala pemahaman konsep di kelas, serta memanfaatkan data rekap skor kuis untuk melakukan diagnosis kelemahan kelas dan menyusun strategi pembelajaran terdiferensiasi pada pertemuan berikutnya."}, {"indikator": "Implementasi dan Penerapan", "pertanyaan": "Jika karya inovasi sudah pernah diimplementasikan, bagaimana proses implementasinya?", "jawaban": "Karya inovasi 'Informatika Learning Hub' telah melalui tahap Implementasi Prototipe Awal (Uji Coba Skala Terbatas) pada pembelajaran Informatika di laboratorium komputer SMKN 1 Banjarmasin, dengan rincian proses sebagai berikut:\n1. Konteks Penerapan: Diuji coba secara terbatas kepada murid kelas X-B DKV (35 murid) pada materi percontohan 'Data, Informasi, dan Validasi' di bawah supervisi Guru Pamong saat praktik mengajar PPL.\n2. Penyampaian Instruksi: Guru membagikan tautan lokal website di laboratorium komputer. Murid diberi waktu 30 menit untuk mengeksplorasi modul teks dan menyaksikan video pengantar yang telah disematkan pada sistem.\n3. Sesi Kuis Formatif Mandiri: Murid mengerjakan paket 10 soal kuis interaktif validasi data secara mandiri melalui layar komputer masing-masing.\n4. Aktivasi Papan Peringkat: Guru menampilkan layar Leaderboard di proyektor laboratorium komputer, yang secara spontan membangkitkan sorak antusiasme dan suasana kompetisi positif di antara murid kejuruan.\nCatatan Batasan Implementasi: Pada tahap prototipe ini, fitur penyimpanan data skor kuis masih menggunakan penyimpanan lokal peramban (local storage/Google Sheets web app hook), dan materi yang tersedia secara lengkap baru mencakup Bab Data, Informasi, dan Validasi. Website belum mencakup seluruh elemen Informatika lainnya (seperti Algoritma Pemrograman dan Jaringan Komputer), yang saat ini masih berstatus rancangan pengembangan tahap selanjutnya."}, {"indikator": "Implementasi dan Penerapan", "pertanyaan": "Jika karya inovasi belum pernah diimplementasikan, bagaimana rancangan proses implementasinya?", "jawaban": "Untuk pengembangan lanjutan berskala luas (penerapan penuh untuk seluruh kelas X SMK dan penambahan seluruh bab kurikulum Informatika), rancangan proses implementasi disusun secara bertahap dan sistematis melalui 8 tahapan berikut:\n1. Tahap Analisis dan Kurasi Konten Kurikulum\nMenelaah Capaian Pembelajaran (CP) dan Alur Tujuan Pembelajaran (ATP) Informatika Fase E Kurikulum Merdeka secara menyeluruh, serta menyusun naskah materi pembelajaran terstruktur berbahasa Indonesia yang padat dan aplikatif.\n2. Tahap Produksi Media Video Pembelajaran\nMembuat dan mengkurasi rekaman video demonstrasi tutorial berdurasi pendek (5–7 menit) dengan kualitas audio-visual yang jernih, bebas dari watermark, dan berfokus langsung pada pemecahan studi kasus komputasi.\n3. Tahap Rekayasa Antarmuka dan Pemrograman Sistem Web\nMembangun kode sistem website yang sepenuhnya responsif, menerapkan prinsip aksesibilitas web (web accessibility), mengoptimalkan kecepatan muat halaman (fast loading speed), serta mengintegrasikan logika penilaian kuis otomatis.\n4. Tahap Pengujian Fungsi Internal (Alpha Testing / Blackbox Testing)\nMelakukan pengetesan mendalam terhadap fungsionalitas seluruh tautan menu, pemutar video, keakuratan sistem penskoran kuis, dan keandalan papan peringkat pada berbagai resolusi layar (laptop, tablet, telepon pintar Android dan iOS).\n5. Tahap Uji Coba Terbatas (Beta / Pilot Testing)\nMenerapkan website kepada kelompok kecil murid (15-20 orang) di luar jam pelajaran untuk mengidentifikasi potensi galat (bugs), kendala navigasi, atau ketidakjelasan kalimat petunjuk soal.\n6. Tahap Pengumpulan Umpan Balik Pengguna\nMenyebarkan kuesioner respon sederhana kepada murid dan meminta telaah ahli materi/rekan guru sejawat mengenai kesesuaian konten dan kemudahan operasional website.\n7. Tahap Perbaikan dan Penyempurnaan (Iterative Refinement)\nMemperbaiki kelemahan tampilan antarmuka, menyempurnakan redaksi penjelasan butir kuis, dan meningkatkan efisiensi kompresi berkas media berdasarkan data hasil uji coba.\n8. Tahap Diseminasi dan Ekspansi Konten Berkelanjutan\nMeluncurkan website secara luas di sekolah untuk seluruh rombongan belajar kelas X SMK, serta memperluas ketersediaan materi ke bab-bab Informatika lainnya (Sistem Komputer, Jaringan Komputer & Internet, Algoritma Pemrograman, dan Dampak Sosial Informatika)."}, {"indikator": "Evaluasi", "pertanyaan": "Bagaiamana tahapan evaluasi untuk mengukur tingkat keberhasilan inovasi tersebut?", "jawaban": "Tahapan evaluasi untuk mengukur tingkat keberhasilan karya inovatif 'Informatika Learning Hub' dirancang secara komprehensif, terukur, dan realistis berdasarkan 7 aspek indikator evaluasi:\n1. Evaluasi Fungsi dan Keandalan Sistem (Functionality Testing)\n• Cara Pengukuran: Pengujian fungsional (blackbox testing) pada seluruh tautan tombol navigasi, pemutar video HTML5, mekanisme pengacakan soal, dan kalkulasi skor kuis.\n• Indikator Keberhasilan: Tingkat kegagalan sistem (error rate) 0%, semua menu merespons dengan cepat, dan skor kuis terhitung 100% akurat tanpa galat logika.\n2. Evaluasi Keselarasan Materi Kurikulum (Curricular Content Validity)\n• Cara Pengukuran: Validasi isi oleh rekan guru senior mata pelajaran Informatika dan Guru Pamong menggunakan lembar telaah keselarasan Capaian Pembelajaran.\n• Indikator Keberhasilan: Seluruh materi teks, video, dan kuis Bab Data, Informasi, dan Validasi dinilai 'Sangat Sesuai' dengan tuntutan Alur Tujuan Pembelajaran (ATP) Fase E Kurikulum Merdeka.\n3. Evaluasi Kemudahan Penggunaan (Usability Evaluation)\n• Cara Pengukuran: Menggunakan instrumen modifikasi kuesioner System Usability Scale (SUS) yang diisi oleh murid setelah menggunakan website.\n• Indikator Keberhasilan: Memperoleh skor SUS minimal 75 (kategori 'Good' / 'Acceptable'), di mana murid menyatakan website mudah dioperasikan secara mandiri tanpa memerlukan bimbingan teknis yang rumit.\n4. Evaluasi Tingkat Keterlibatan Murid (Engagement Metrics)\n• Cara Pengukuran: Pengamatan observasi keaktifan kelas saat sesi belajar mandiri dan pemeriksaan log frekuensi pengerjaan kuis pada sistem.\n• Indikator Keberhasilan: Lebih dari 85% murid menyelesaikan seluruh rangkaian modul materi, menyaksikan video hingga tuntas, dan berpartisipasi aktif dalam kuis interaktif.\n5. Evaluasi Respons dan Persepsi Pengguna (User Feedback)\n• Cara Pengukuran: Angket kepuasan murid berskala Likert (1–5) serta wawancara singkat mengenai kenyamanan antarmuka, kejelasan bahasa Indonesia yang digunakan, dan daya tarik leaderboard.\n• Indikator Keberhasilan: Rata-rata skor kepuasan murid mencapai minimal 4.2 dari skala 5.0, dengan testimoni kualitatif yang menunjukkan peningkatan antusiasme belajar.\n6. Evaluasi Capaian Hasil Belajar (Learning Outcomes Evaluation)\n• Cara Pengukuran: Menganalisis perbandingan nilai sebelum penggunaan media (pre-test) dan sesudah penggunaan media (post-test) berbantuan formula N-Gain ternormalisasi.\n• Indikator Keberhasilan: Terjadi peningkatan nilai kognitif murid dengan perolehan skor N-Gain minimal dalam kategori 'Sedang' (g ≥ 0.3) hingga 'Tinggi' (g ≥ 0.7), serta ketuntasan klasikal kelas mencapai di atas 85%.\n7. Rencana Tindak Lanjut Evaluasi (Action Plan for Improvement)\n• Implementasi: Mengolah seluruh temuan evaluasi untuk melakukan perbaikan berkala: memperbaiki tampilan antarmuka seluler, menyempurnakan butir soal kuis yang memiliki daya pembeda rendah, menambahkan fitur pencarian materi cepat (search box), serta mengembangkan modul bab berikutnya secara bertahap."}, {"indikator": "1.", "pertanyaan": "Kebaruan (Novelty)", "jawaban": "Produk mengandung unsur baru, baik ide, pendekatan, maupun cara penerapan yang belum pernah digunakan sebelumnya dalam konteks yang sama."}, {"indikator": "2.", "pertanyaan": "Kreativitas", "jawaban": "Dihasilkan melalui proses berpikir kreatif yang mengombinasikan ide, teori, atau teknologi untuk memecahkan masalah pendidikan."}, {"indikator": "3.", "pertanyaan": "Kebermanfaatan (Usefulness)", "jawaban": "Memberikan nilai tambah bagi peserta didik, guru, atau lembaga pendidikan dalam meningkatkan efektivitas dan efisiensi pembelajaran."}, {"indikator": "4.", "pertanyaan": "Relevansi dan Kontekstualitas", "jawaban": "Sesuai dengan kebutuhan peserta didik, karakteristik kurikulum, serta perkembangan teknologi dan masyarakat."}, {"indikator": "5.", "pertanyaan": "Efektivitas Terbukti (Evidence-Based)", "jawaban": "Teruji melalui uji coba atau penelitian yang menunjukkan adanya peningkatan hasil belajar, motivasi, atau keterampilan."}]}, "sem1-filosofi": {"title": "LEMBAR KERJA 2 (LK 2) — FILOSOFI PENDIDIKAN DAN PENDIDIKAN NILAI", "filename": "LK Refleksi Semester 1 Filosofi Pendidikan dan Pendidikan Nilai  _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 1 Filosofi Pendidikan dan Pendidikan Nilai  _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini memberikan fondasi filosofis yang sangat mendasar bagi peran saya sebagai calon guru Informatika di SMKN 1 Banjarmasin. Sebelum mendalami materi ini, saya cenderung memandang pengajaran Informatika secara teknis-pragmatis semata, terfokus kaku pada penguasaan sintaks perangkat lunak, formula spreadsheet, dan pengoperasian komputer.\nSetelah mempelajari pemikiran Ki Hadjar Dewantara (KHD) dan hakikat pendidikan nilai, saya menyadari keterkaitan erat antara teknologi informasi dengan kodrat kemanusiaan. Mengajar Informatika di SMK bukan sekadar mentransfer kecakapan digital mekanis, melainkan ikhtiar 'menuntun segala kodrat yang ada pada anak' agar mereka tumbuh menjadi manusia berdaya, berakhlak mulia, dan memiliki etika digital di era kecerdasan buatan. Hal ini sangat nyata ketika saya mengajar di kelas X-B DKV dan X-C DKV, di mana murid memiliki daya cipta visual tinggi namun memerlukan bimbingan budi pekerti dalam memanfaatkan teknologi informasi secara beretika dan bijaksana."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan terbesar yang mendisrupsi cara pandang saya adalah tuntutan untuk membongkar asumsi bahwa pembelajaran teknologi itu netral nilai dan seragam. Praktik yang sering saya lakukan sebelumnya adalah menganggap bahwa ketika materi teknis telah disampaikan tuntas di depan kelas, maka tugas mengajar telah selesai.\nKenyataannya, saat berhadapan langsung dengan murid kelas X-B DKV dan X-C DKV di laboratorium komputer SMKN 1 Banjarmasin, saya menemukan dinamika sosiokultural yang sangat beragam. Murid DKV memiliki karakter ekspresif dan mudah terdistraksi oleh media sosial serta hiburan digital saat layar monitor menyala. Materi perkuliahan ini menantang saya bahwa guru tidak boleh bertindak sebagai mandor yang memaksakan kehendak atau sekadar menuntut kepatuhan teknis, melainkan harus hadir sebagai pamong yang menginternalisasikan nilai-nilai integritas, kejujuran intelektual atas hak cipta karya digital, dan tanggung jawab sosial."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep esensial yang menjadi kompas pedagogis saya meliputi:\n• Sistem Among Ki Hadjar Dewantara: Prinsip Ing Ngarso Sung Tulodo (memberikan keteladanan literasi digital), Ing Madyo Mangun Karso (membangun semangat kolaborasi di laboratorium), dan Tut Wuri Handayani (memberikan dorongan kemandirian berkarya).\n• Kodrat Alam dan Kodrat Zaman: Menyadari bahwa murid SMK hidup di era disrupsi informasi global (kodrat zaman), namun tetap berakar kuat pada nilai kearifan lokal dan budaya kesantunan Banjar (kodrat alam).\n• Pendidikan Nilai dan Budi Pekerti: Keseimbangan cipta, rasa, dan karsa, sehingga kecanggihan teknologi komputasi selalu dipandu oleh nurani moral dan kepedulian sosial.\n• Pendidikan Humanistis yang Berpihak pada Murid: Menjadikan kebutuhan, potensi, dan keselamatan batin murid sebagai poros utama dalam merancang setiap pengalaman belajar Informatika."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Perubahan nyata yang saya terapkan dalam praktik mengajar di kelas X-B DKV dan X-C DKV adalah:\n• Pergeseran Paradigma Mengajar: Mentransformasi pendekatan dari transfer of knowledge teknis semata menuju transfer of values, menuntun etika bermedia digital dan integritas orisinalitas karya.\n• Desain Pembelajaran yang Memanusiakan Hubungan: Merancang modul ajar TIK yang memuat kesepakatan kelas ramah dan partisipatif, serta mengintegrasikan nilai gotong royong dalam penugasan proyek laboratorium komputer.\n• Keteladanan Digital (Digital Role Model): Membiasakan diri memberikan teladan dalam penggunaan sumber belajar yang legal, menghormati lisensi karya cipta, dan membangun komunikasi yang apresiatif kepada setiap murid."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran yang saya jadikan bukti dukung otentik adalah:\n• Ringkasan Jurnal Refleksi Topik 1: Telaah Kritis Pokok-Pokok Pikiran Ki Hadjar Dewantara dalam Transformasi Pendidikan Kejuruan.\n• Perangkat Modul Ajar TIK Terintegrasi Profil Pelajar Pancasila: Modul Ajar Informatika Fase E pada materi Literasi Digital dan Pengolahan Data di SMKN 1 Banjarmasin yang memuat rubrik dimensi Beriman & Berakhlak Mulia, Gotong Royong, dan Bernalar Kritis.\n• Laporan Tugas Aksi Nyata: Sintesis Kontekstual Filosofi KHD dalam Praktik Mengajar Informatika di Laboratorium Komputer SMK."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena merekam secara nyata proses rekonstruksi cara berpikir saya: dari yang awalnya menyusun modul praktikum murni berbasis instruksi langkah teknis (mekanistik), berubah menjadi modul yang menanamkan kesadaran kritis, etika digital, dan kerja sama antar-murid.\nDokumen modul ajar dan jurnal refleksi tersebut menjadi saksi tertulis bagaimana prinsip menuntun dioperasionalkan ke dalam skenario kelas nyata di SMKN 1 Banjarmasin."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Modul Ajar TIK (khususnya Bagian 1.E Kegiatan Pembelajaran dan Rubrik Asesmen Sikap), tercantum secara eksplisit langkah apersepsi reflektif di awal pertemuan dan penegasan etika siber sebelum murid membuka peramban web.\nSelain itu, rubrik penilaian kolaborasi kelompok praktikum menilai bagaimana murid kelompok mahir membantu rekannya (scaffolding) dengan penuh empati, mencerminkan pembumian nilai gotong royong dan asas kebersamaan Ki Hadjar Dewantara di ruang praktikum."}]}, "sem1-ppdp": {"title": "LEMBAR KERJA 2 (LK 2) — PEMAHAMAN TENTANG PESERTA DIDIK DAN PEMBELAJARAN", "filename": "LK Refleksi Semester 1 Pemahaman tentang Peserta Didik dan Pembelajaran _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 1 Pemahaman tentang Peserta Didik dan Pembelajaran _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini memiliki relevansi langsung dengan realitas yang saya hadapi sehari-hari saat mengajar kelas X-B DKV dan X-C DKV di SMKN 1 Banjarmasin. Di dalam kelas kejuruan, murid datang dengan latar belakang kognitif, modal pengalaman gawai, serta minat belajar yang sangat berjarak.\nTanpa pemahaman yang utuh mengenai psikologi perkembangan remaja dan keragaman cara belajar, seorang guru Informatika berisiko menggeneralisasi kemampuan murid. Mata kuliah ini menghubungkan fakta empiris di lapangan dengan teori-teori perkembangan kognitif, sosiokultural, dan moral, sehingga membuka mata saya bahwa merancang pengajaran harus selalu berpijak pada data profil kesiapan belajar (learner profiling)."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Materi perkuliahan yang paling menantang kebiasaan lama saya adalah kewajiban meninggalkan pendekatan one-size-fits-all (pengajaran seragam dengan satu tempo penjelasan). Sebelumnya, saya terbiasa menjelaskan materi di proyektor laboratorium dengan asumsi jika langkah-langkah sudah didemonstrasikan dengan jelas, semua murid pasti mampu mengikutinya.\nKenyataannya, saat mengajar kelas X-B DKV, sebagian murid langsung menguasai formula spreadsheet dan logika pengurutan data dalam 15 menit, sementara sebagian lain (kelompok Perintis) masih bingung membedakan sintaks alamat sel dan fungsi dasar matematika. Materi perkuliahan ini menantang saya untuk mendesain pembelajaran berdiferensiasi (konten, proses, produk) yang adaptif terhadap profil belajar murid SMK."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep pokok yang berhasil saya kuasai dan internalisasikan antara lain:\n• Teori Perkembangan Kognitif (Piaget & Vygotsky): Konsep Zone of Proximal Development (ZPD) dan pemberian bantuan bertahap (scaffolding) yang tepat sasaran hingga murid mencapai kemandirian bernalar.\n• Teori Psikososial Erik Erikson: Dinamika pencarian identitas diri dan peran sosial remaja SMK usia 15–17 tahun, yang membutuhkan validasi positif, apresiasi karya, dan rasa dihargai di lingkungan kelas.\n• Pembelajaran Berdiferensiasi (Differentiated Instruction): Penyesuaian konten materi, proses pendampingan, variasi bentuk luaran produk tugas, serta pengaturan lingkungan belajar fisik maupun digital.\n• Asesmen Diagnostik Awal: Instrumen diagnostik non-kognitif (gaya belajar & psikososial) dan kognitif (kesiapan materi prasyarat) sebelum memulai bab baru."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Langkah perbaikan konkret yang saya wujudkan di kelas X-B DKV dan X-C DKV meliputi:\n• Melakukan Pemetaan Kesiapan Belajar Rutin: Melaksanakan asesmen awal sebelum topik pengolahan data dimulai, memetakan 35 murid kelas X-B DKV ke dalam 3 tingkatan kesiapan: Perintis, Cakap, dan Mahir.\n• Menerapkan Proyek Praktikum Bertingkat (Tiered Assignment): Memberikan lembar kerja bertahap; kelompok Perintis didampingi panduan visual langkah-demi-langkah, kelompok Cakap mengerjakan modul analitis mandiri, dan kelompok Mahir diberikan tantangan pengayaan studi kasus nyata.\n• Menyediakan Jalur Ekspresi yang Fleksibel: Mengakomodasi karakteristik anak DKV yang visual-spasial untuk mempresentasikan laporan hasil analisis komputasi mereka dalam bentuk infografis atau dashboard visual yang menarik."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran yang mendukung refleksi ini meliputi:\n• Instrumen dan Lembar Hasil Profiling Peserta Didik Kelas X SMK: Berkas analisis gaya belajar (visual, auditori, kinestetik) dan inventarisasi akses fasilitas komputer siswa di rumah.\n• Dokumen Analisis Kasus Pembelajaran (Tugas Ruang Kolaborasi LK 1.a & LK 2.a): Analisis penanganan murid yang mengalami hambatan kognitif dan demotivasi belajar di kelas laboratorium.\n• Tabel Pemetaan Diferensiasi Modul Ajar TIK: Dokumen skenario pembelajaran berdiferensiasi proses dan produk pada praktikum analisis data."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena menyediakan data empiris autentik mengenai kondisi murid binaan saya di SMKN 1 Banjarmasin. Bukti dokumen profiling dan tabel diferensiasi membuktikan bahwa rancangan pembelajaran yang saya susun tidak lahir dari asumsi teoretis kosong, melainkan berangkat dari potret nyata kebutuhan belajar murid di ruang kelas."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Lembar Hasil Profiling dan Tabel Diferensiasi (LK 2.a), terlihat secara jelas pembagian 3 tingkatan scaffolding pada materi pemanfaatan aplikasi spreadsheet: kelompok Perintis difasilitasi dengan lembar panduan bergambar kartu kendali, sedangkan kelompok Mahir difungsikan sebagai tutor sebaya (peer-scaffolding) bagi kelompok yang membutuhkan bimbingan teknis."}]}, "sem1-pma-dasar": {"title": "LEMBAR KERJA 2 (LK 2) — PEMBELAJARAN MENDALAM DAN ASESMEN DASAR", "filename": "LK Refleksi Semester 1 Pembelajaran Mendalam dan Asesmen Dasar _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 1 Pembelajaran Mendalam dan Asesmen Dasar _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini merevolusi pemahaman saya mengenai hakikat pembelajaran dan penilaian dalam bidang Informatika. Selama ini, pelajaran TIK kerap terjebak dalam surface learning (belajar di permukaan), di mana murid hanya menghafal letak menu, menghafal fungsi formula tanpa memahami maknanya, atau mengetik ulang langkah praktikum secara mekanis.\nPerkuliahan PMA Dasar menghubungkan penguasaan teknologi dengan penalaran komputasional (computational thinking) mendalam. Guru Informatika dituntut mampu memandu murid menghubungkan konsep teoritis dengan pemecahan masalah riil dalam kehidupan sehari-hari, didukung oleh sistem asesmen yang holistik dan autentik."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Perbedaan mendasar terletak pada pergeseran dari 'mengajar materi' menjadi 'merancang pencapaian pemahaman esensial'. Dulu, saya beranggapan bahwa semakin banyak materi dan rumus yang dijejalkan dalam satu pertemuan, maka pembelajaran semakin baik. Asesmen pun hanya saya posisikan sebagai evaluasi akhir (assessment of learning) berupa tes pilihan ganda berbobot angka kaku.\nMata kuliah ini menyadarkan saya bahwa pembelajaran mendalam menuntut prinsip 3B: Berkesadaran (Mindful), Bermakna (Meaningful), dan Menggembirakan (Joyful). Asesmen harus diposisikan sebagai sarana belajar (assessment as learning) dan pemantauan proses (assessment for learning) melalui umpan balik formatif yang memberdayakan murid."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep inti yang saya kuasai meliputi:\n• Kerangka Pembelajaran Mendalam (Deep Learning): Alur siklus Memahami (Acquiring Knowledge), Mengaplikasikan (Applying Knowledge to Real Problems), dan Merefleksikan (Reflecting on Metacognition).\n• Understanding by Design (UbD) / Backward Design: Perancangan pembelajaran alur mundur yang dimulai dari identifikasi hasil yang diinginkan (Capaian Pembelajaran & Pertanyaan Esensial), penentuan bukti asesmen autentik, baru kemudian menyusun kegiatan belajar.\n• Tripartit Asesmen: Keseimbangan integratif antara Assessment as Learning (refleksi diri dan asesmen antarteman), Assessment for Learning (umpan balik formatif berkala selama praktikum), dan Assessment of Learning (sumatif ketercapaian tujuan).\n• Taksonomi SOLO dan Berpikir Kritis: Panduan mengukur lompatan kognitif murid dari taraf unistruktural ke relasional dan abstrak diperluas."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Perubahan nyata yang saya terapkan pada pembelajaran TIK kelas X-B DKV dan X-C DKV di SMKN 1 Banjarmasin adalah:\n• Menerapkan Backward Design secara Disiplin: Merumuskan modul ajar dengan diawali Pertanyaan Esensial (misal: 'Bagaimana data angka dapat diubah menjadi visual informasi yang menyelamatkan keputusan publik?').\n• Mengaitkan Data dengan Konteks Nyata: Mengganti data latihan fiktif yang kering dengan dataset autentik kearifan lokal (misal data fluktuasi elevasi air Waduk Riam Kanan Kalimantan Selatan) agar murid merasakan relevansi analisis data.\n• Mengintegrasikan Tiket Keluar (Exit Ticket): Menyediakan waktu 10 menit di akhir sesi praktikum untuk refleksi tertulis singkat mengenai apa yang telah dipahami dan kendala logika apa yang masih dihadapi."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran yang mendukung refleksi ini antara lain:\n• Peta Konsep Digital (Mind Map) Deep Learning vs Surface Learning (LK 1.2): Analisis perbandingan karakteristik pembelajaran mendalam pada rumpun teknologi kejuruan.\n• Modul Ajar TIK Berbasis Backward Design (UbD): Perangkat Modul Ajar Elemen Literasi Digital Fase E topik Integrasi Aplikasi Perkantoran di SMKN 1 Banjarmasin.\n• Rubrik Asesmen Autentik Praktikum: Lembar asesmen unjuk kerja pemecahan masalah data berbantuan spreadsheet terintegrasi ke dokumen pengolah kata dan presentasi."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena mendokumentasikan kompetensi saya dalam menerapkan prinsip keselarasan pedagogis (constructive alignment). Modul Ajar UbD membuktikan bagaimana tujuan pembelajaran, instrumen asesmen unjuk kerja, dan aktivitas eksplorasi praktikum saling terikat erat dan terarah pada pemahaman konseptual yang kokoh."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Modul Ajar UbD Bagian 2 (Bukti dan Asesmen), terdapat instrumen asesmen formatif berkelanjutan beserta rubrik performa analitis (memuat kriteria penalaran data, akurasi formula, dan estetika visualisasi). Hal ini membuktikan bahwa penilaian di lab komputer tidak lagi sekadar memeriksa hasil akhir file tersimpan, melainkan menilai kedalaman proses penalaran murid saat memecahkan masalah."}]}, "sem1-sosiokultural": {"title": "LEMBAR KERJA 2 (LK 2) — PERSPEKTIF SOSIOKULTURAL DALAM PENDIDIKAN INDONESIA", "filename": "LK Refleksi Semester 1 Perspektif Sosiokultural dalam Pendidikan Indonesia _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 1 Perspektif Sosiokultural dalam Pendidikan Indonesia _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini memperluas wawasan saya bahwa ruang kelas di sekolah tidak pernah berdiri di ruang hampa yang terisolasi dari lingkungan sosialnya. Pendidikan selalu terikat erat dengan latar belakang ekonomi keluarga, modal kultural, serta dinamika komunitas lokal tempat anak tumbuh.\nHal ini sangat relevan dengan kenyataan di SMKN 1 Banjarmasin. Murid-murid kelas X-B DKV dan X-C DKV memiliki latar belakang keluarga yang sangat beragam: sebagian memiliki laptop pribadi berspesifikasi tinggi di rumah, sementara sebagian lainnya hanya mengandalkan gawai sederhana (smartphone) dengan kuota terbatas dan sama sekali tidak memiliki komputer pribadi di rumah. Pemahaman sosiokultural membantu saya merancang pembelajaran TIK yang berkeadilan dan tidak diskriminatif."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan terbesar bagi saya adalah mengikis bias kelas menengah dan asumsi bahwa semua murid SMK memiliki kemudahan akses teknologi yang sama di luar sekolah. Di masa lalu, guru kerap memberikan tugas rumah praktikum berbasis komputer tanpa memikirkan apakah murid memiliki fasilitas pendukung di kediamannya.\nPerkuliahan ini menuntut saya untuk bersikap tanggap budaya dan peka secara sosial (culturally and socially responsive). Saya belajar meniadakan pekerjaan rumah berbasis komputer yang membebani, mengoptimalkan jam praktikum di laboratorium sekolah secara maksimal, serta membuka akses laboratorium komputer di luar jam pelajaran bagi murid yang membutuhkan waktu latihan tambahan."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep fundamental yang saya pelajari meliputi:\n• Zone of Proximal Development (ZPD) dan Scaffolding (Lev Vygotsky): Peran interaksi sosial, mediasi alat budaya (teknologi), dan bantuan tutor sebaya dalam menjembatani jarak antara kemampuan aktual murid dengan kemampuan potensialnya.\n• Teori Sistem Ekologi (Urie Bronfenbrenner): Pengaruh mikrosistem (keluarga, teman sebaya), mesosistem (relasi sekolah dan orang tua), eksosistem, makrosistem (kebijakan digital nasional), serta kronosistem terhadap perkembangan belajar murid.\n• Modal Sosial dan Kultural (Pierre Bourdieu): Menghargai modal budaya yang dibawa murid dari rumah dan mengubahnya menjadi jembatan pembelajaran di sekolah.\n• Pendidikan Tanggap Kebudayaan (Culturally Responsive Teaching - CRT): Menyelaraskan konten pembelajaran dengan nilai-nilai kearifan lokal masyarakat lahan basah Kalimantan Selatan."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Aksi nyata yang saya terapkan di lingkungan SMKN 1 Banjarmasin adalah:\n• Mengoptimalkan Laboratorium Sekolah sebagai Ruang Kesetaraan: Menjamin seluruh penugasan praktikum berbasis perangkat lunak diselesaikan tuntas di laboratorium sekolah tanpa mewajibkan pengerjaan di rumah bagi murid yang tidak berfasilitas.\n• Menerapkan Model Tutor Sebaya yang Terstruktur: Memasangkan murid yang memiliki kecakapan digital awal lebih tinggi dengan murid yang membutuhkan bantuan dalam kelompok kerja yang suportif.\n• Mengintegrasikan Kearifan Lokal Banjar ke Materi TIK: Membawa isu-isu lingkungan lokal (seperti pengelolaan limbah sungai, ekosistem pasar terapung, dan data hidrologi lahan basah) sebagai tema proyek pengolahan data Informatika."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran yang mendukung refleksi ini meliputi:\n• Makalah dan Lembar Kerja Analisis Kasus Sosiokultural Murid SMK (Tugas Ruang Kolaborasi Topik 2): Studi mendalam mengenai kesenjangan akses teknologi dan dampaknya terhadap capaian literasi digital siswa di perkotaan dan pinggiran Banjarmasin.\n• Modul Ajar TIK Berpendekatan Culturally Responsive Teaching (CRT): Perangkat ajar pengolahan data kontekstual yang mengkaji potensi sosial ekonomi daerah Kalimantan Selatan.\n• Laporan Observasi Ekologi Belajar Murid SMKN 1 Banjarmasin: Pemetaan faktor pendukung dan penghambat belajar murid di lingkungan keluarga dan pertemanan."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena membuktikan kepekaan sosiologis saya sebagai guru. Dokumen tersebut memperlihatkan bagaimana teori Vygotsky dan Bronfenbrenner bukan sekadar wacana teoritis di perkuliahan, melainkan saya jadikan lensa untuk mendiagnosis kendala belajar murid secara adil dan empatik."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Makalah Analisis Kasus Sosiokultural Bagian Pembahasan, terpapar strategi intervensi pedagogis berupa pembentukan kelompok kerja heterogen berbasis ZPD. Hal ini secara konkret diimplementasikan dalam skenario Modul Ajar TIK di mana setiap kelompok praktikum beranggotakan kombinasi murid dari berbagai latar belakang kesiapan teknologi."}]}, "sem1-growth-mindset": {"title": "LEMBAR KERJA 2 (LK 2) — POLA PIKIR BERTUMBUH DALAM PEMBELAJARAN", "filename": "LK Refleksi Semester 1 Pola Pikir Bertumbuh dalam Pembelajaran _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 1 Pola Pikir Bertumbuh dalam Pembelajaran _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini menyentuh aspek psikologis yang sangat krusial dalam pembelajaran Informatika di SMK. Belajar komputasi, logika pemrograman, dan pengolahan data identik dengan trial-and-error, pesan kesalahan (error warning), sintaks yang keliru, serta sistem yang mogok bekerja.\nDi kelas X-B DKV dan X-C DKV SMKN 1 Banjarmasin, murid yang terbiasa berpikir estetis sering kali merasa tertekan, minder, atau cepat menyerah saat menemui formula spreadsheet yang menghasilkan kode error `#VALUE!` atau `#N/A`. Materi pola pikir bertumbuh (growth mindset) menghubungkan psikologi kognitif dan neurosains dengan peran guru sebagai pembangun daya lentur (resilience) dan ketahanan mental murid dalam menghadapi kerumitan teknologi."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan paling menggugah kesadaran saya adalah menyadari bahwa tanpa sengaja, cara guru memberikan pujian kerap kali justru memicu fixed mindset. Dulu, saya sering memuji murid yang selesai lebih cepat dengan kalimat: 'Wah, kamu pintar sekali dan berbakat di komputer!'\nPerkuliahan ini mengajarkan bahwa pujian berbasis bakat bawaan membuat murid takut mencoba hal baru karena takut kehilangan label 'pintar'. Sebaliknya, guru harus menggeser budaya kelas dari orientasi performa instan menjadi apresiasi terhadap proses kerja keras, strategi debugging, dan ketekunan (effort and process praise). Kesalahan dalam komputasi bukanlah bukti kebodohan, melainkan data berharga untuk belajar."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep esensial yang saya serap dari mata kuliah ini meliputi:\n• Teori Dikotomi Pola Pikir (Carol Dweck): Perbedaan mendasar antara Fixed Mindset (kecerdasan dianggap bawaan statis) vs Growth Mindset (kecerdasan dapat dikembangkan melalui latihan, strategi tepat, dan ketekunan).\n• Neuroplastisitas Otak: Fakta ilmiah bahwa koneksi sinapsis di otak terus tumbuh dan menguat saat seseorang memecahkan tantangan rumit dan belajar dari kegagalan.\n• Konsep Kegagalan Produktif (Productive Failure): Memposisikan error dan kekeliruan analisis data sebagai sarana eksplorasi kognitif yang memicu pemahaman lebih dalam.\n• The Power of Yet ('Kekuatan Kata BELUM'): Mengubah vonis 'Saya tidak bisa koding/rumus ini' menjadi 'Saya belum bisa menguasai rumus ini saat ini, mari coba strategi lain'.\n• Opportunity-Based Thinking: Memandang keterbatasan sarana laboratorium sebagai pemantik kreativitas pemecahan masalah alternatif."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Perubahan nyata yang saya budayakan di laboratorium komputer SMKN 1 Banjarmasin adalah:\n• Mengubah Pola Umpan Balik (Reframing Feedback): Memuji proses penalaran murid: 'Saya bangga dengan ketekunanmu melacak sel yang salah hitung selama 20 menit tadi, strategi pemeriksaanmu sangat sistematis.'\n• Menciptakan Zona Aman Berbuat Salah (Psychological Safety Zone): Menggelar sesi 'Merayakan Error': murid tidak perlu merasa malu saat layarnya menampilkan error, melainkan mengajak teman sebelahnya mendiskusikan penyebab logikanya secara terbuka.\n• Menanamkan Refleksi Diri Bertumbuh: Membiasakan murid mencatat kendala praktikum di jurnal belajar dengan menanyakan: 'Apa yang saya pelajari dari kekeliruan langkah saya hari ini?'"}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran pendukung yang relevan terdiri atas:\n• Lembar Kerja LK 1.1 'Cara Pikirmu, Cermin Dirimu' & LK 2.4 'Dari Aduh Saya Gagal ke Saya Bisa': Rekaman analisis diri dan rekonstruksi bahasa komunikasi guru dalam kelas.\n• Tabel Reframing Respon Guru (Tugas Ruang Kolaborasi LK 4.2): Panduan kalimat penguatan berbasis pertumbuhan untuk menangani keputusasaan murid saat mengalami galat (error) praktikum.\n• Rancangan Aktivitas Kelas 'The Power of Yet': Desain poster afirmasi pola pikir bertumbuh yang ditempel di dinding laboratorium komputer SMKN 1 Banjarmasin."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena merekam instrumen praktis yang langsung mengubah iklim psikologis di kelas. Dokumen tabel reframing respon membuktikan kesiapan saya dalam memodifikasi dialog instruksional menjadi dialog yang menguatkan resiliensi murid vokasi."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Tabel Reframing Respon Guru (LK 4.2), terdapat komparasi langsung respon guru pada studi kasus murid SMK yang frustrasi menghadapi tugas formula bercabang di Excel. Kolom respon baru menunjukkan bagaimana instruksi diubah dari teguran menjadi pertanyaan pemandu (scaffolding question) yang merangsang neuroplastisitas murid."}]}, "sem1-ppl-terbimbing": {"title": "LEMBAR KERJA 2 (LK 2) — PRAKTIK PENGALAMAN LAPANGAN (PPL) TERBIMBING", "filename": "LK Refleksi Semester 1 Praktik Pengalaman Lapangan Terbimbing _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 1 Praktik Pengalaman Lapangan Terbimbing _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "PPL Terbimbing di SMKN 1 Banjarmasin merupakan laboratorium nyata yang menyatukan seluruh mata kuliah teoritis, filosofi KHD, pemahaman peserta didik, dan kerangka Deep Learning, ke dalam panggung praktik mengajar sesungguhnya.\nMenghadapi 35 murid kelas X-B DKV dan X-C DKV di laboratorium komputer menuntut integrasi instan antara penguasaan materi teknis, keterampilan komunikasi kelas, kewaspadaan manajemen waktu, dan kepekaan pedagogis di bawah bimbingan intensif Guru Pamong dan Dosen Pembimbing Lapangan (DPL)."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan riil yang mendidik mentalitas profesional saya di lapangan sangat kompleks, antara lain:\n• Manajemen Waktu yang Ketat: Dalam durasi 3 JP (120 menit), mengalokasikan waktu apersepsi (15 menit), demonstrasi konsep (25 menit), praktikum terbimbing (55 menit), dan asesmen refleksi (25 menit) sering kali meleset jika murid mengalami hambatan teknis.\n• Manajemen Kelas dan Distraksi Laboratorium: Murid DKV sangat aktif dan mudah tergoda membuka aplikasi grafis lain, menonton YouTube, atau bermain game saat guru menjelaskan di depan kelas.\n• Kendala Teknis Mendadak: Mengalami situasi nyata seperti jaringan LAN lab komputer yang putus, komputer murid hang saat input data, hingga saklar MCB listrik laboratorium yang mendadak trip karena beban daya pendingin ruangan dan PC."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep praktis utama yang saya kuasai selama PPL Terbimbing adalah:\n• Siklus Lesson Study (Plan, Do, See): Tahapan kolaboratif merencanakan perangkat pembelajaran bersama Guru Pamong, melaksanakan praktik mengajar terbimbing, dan melakukan refleksi klinis pasca-mengajar secara jujur.\n• Real-Time Classroom & Laboratory Management: Keterampilan mengatur pandangan mata (*withitness*), berkeliling memantau layar murid (*active circulation*), dan menetapkan komando kelas yang tegas namun ramah (*hands-off-mouse rules*).\n• Adaptive Instructional Contingency (Rencana Cadangan/Plan B): Kesiapan mental dan teknis beralih ke aktivitas unplugged/lembar analog saat sistem komputer atau aliran listrik mengalami gangguan mendadak.\n• Supervisi Klinis Konstruktif: Memanfaatkan setiap butir catatan evaluasi Guru Pamong untuk memperbaiki gestur, intonasi suara, dan efektivitas apersepsi di siklus berikutnya."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Transformasi diri yang saya alami setelah menjalani siklus PPL Terbimbing adalah:\n• Menjadi Calon Guru yang Taktis dan Adaptif: Tidak lagi mudah panik saat kendala teknis terjadi di laboratorium, melainkan langsung mengarahkan murid ke skenario diskusi analog pemecahan masalah data.\n• Penerapan Kontrak Belajar Lab yang Disepakati Bersama: Menegakkan aturan disiplin layar (murid memposisikan monitor mati atau tidak menyentuh papan ketik saat penjelasan konsep kunci berlangsung).\n• Konsistensi Melakukan Refleksi Pasca-Mengajar: Menjadikan masukan Guru Pamong sebagai instrumen kalibrasi harian demi menyempurnakan interaksi belajar murid."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran otentik yang mendukung refleksi ini meliputi:\n• Perangkat Pembelajaran PPL Terbimbing Siklus 1 & 2: Modul Ajar TIK Fase E Elemen Literasi Digital materi Pengolahan Data Waduk Riam Kanan, LKPD Praktikum, Bahan Tayang, dan Lembar Asesmen.\n• Video Rekaman Praktik Mengajar Terbimbing (Durasi Penuh dan Cuplikan 15 Menit): Bukti rekaman unjuk kerja pengelolaan kelas di lab komputer SMKN 1 Banjarmasin.\n• Lembar Observasi dan Catatan Refleksi Supervisi Klinis Guru Pamong & DPL: Lembar penilaian performa mengajar yang memuat umpan balik langsung pembimbing."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena merepresentasikan unjuk kerja faktual saya di ruang kelas nyata. Catatan observasi berkala dari Guru Pamong dan video praktik mengajar membuktikan adanya grafik perkembangan kompetensi pedagogik dan kepribadian saya dari pertemuan awal hingga akhir siklus terbimbing."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Lembar Observasi Guru Pamong Siklus 2, tercantum catatan apresiasi mengenai peningkatan signifikan dalam aspek 'Penguasaan Suasana Laboratorium' dan 'Manajemen Alokasi Waktu Praktikum'. Hal ini selaras dengan video rekaman pada menit ke-45 yang memperlihatkan keberhasilan saya mengkondisikan 35 murid kelas X-B DKV fokus melakukan praktikum pengolahan data mandiri."}]}, "sem2-lahan-basah": {"title": "LEMBAR KERJA 2 (LK 2) — INOVASI PEMBELAJARAN DI LAHAN BASAH", "filename": "LK Refleksi Semester 2 Inovasi Pembelajaran di Lahan Basah  _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 2 Inovasi Pembelajaran di Lahan Basah  _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah muatan lokal khas Universitas Lambung Mangkurat (ULM) ini menautkan identitas keilmuan saya dengan ekosistem geografis dan sosiokultural Kalimantan Selatan. Wilayah lahan basah (wetland), yang kaya akan sungai, rawa pasang surut, hutan gambut, dan waduk hidrologi, memerlukan generasi muda yang peduli terhadap pelestarian lingkungannya.\nSebagai calon guru Informatika di SMKN 1 Banjarmasin, mata kuliah ini menyadarkan saya bahwa teknologi komputasi tidak boleh terisolasi dari lingkungan sekitarnya. Pengajaran Informatika dapat dan harus menjadi instrumen digital untuk menganalisis, mendokumentasikan, dan memecahkan permasalahan nyata yang dihadapi masyarakat lahan basah."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan terbesar yang mendisrupsi pandangan saya adalah stereotip lama bahwa topik lahan basah, lingkungan hidup, dan ekologi adalah monopoli mata pelajaran IPA, Geografi, atau Biologi. Di masa lalu, pengajaran TIK hanya menggunakan studi kasus fiktif dari buku teks luar negeri (seperti data penjualan barang toko retail di Amerika atau Eropa) yang jauh dari keseharian murid.\nMata kuliah ini menantang saya untuk melakukan inovasi interdisipliner melalui kerangka TPACK (Technological Pedagogical Content Knowledge): bagaimana data mentah lingkungan lokal diolah menggunakan peranti spreadsheet, disajikan dalam infografis visual oleh anak DKV, dan diintegrasikan ke dalam laporan digital yang berbobot."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep esensial yang saya peroleh meliputi:\n• Karakteristik Ekosistem Lahan Basah Kalimantan Selatan: Potensi dan kerentanan lingkungan sungai, gambut, rawa, serta infrastruktur pengairan seperti Waduk Riam Kanan.\n• Kerangka Kerja TPACK (Mishra & Koehler): Integrasi harmonis antara materi keilmuan Informatika (Content Knowledge), strategi pedagogik aktif (Pedagogical Knowledge), dan pemanfaatan perangkat lunak digital (Technological Knowledge).\n• Desain Modul Pembelajaran Berwawasan Lingkungan: Perumusan masalah autentik lahan basah sebagai pemicu (trigger) eksplorasi kognitif murid kejuruan.\n• Inovasi Media Digital Kontekstual: Pemanfaatan teknologi komputasi untuk kampanye konservasi lahan basah dan mitigasi bencana lokal (seperti pencegahan kebakaran hutan dan lahan gambut/karhutla)."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Inovasi nyata yang saya terapkan dalam praktik pembelajaran di SMKN 1 Banjarmasin adalah:\n• Mengontekstualisasikan Dataset Praktikum: Menyusun berkas studi kasus praktikum analisis data menggunakan simulasi data fluktuasi elevasi air, curah hujan, dan debit air Waduk Riam Kanan selama 12 bulan.\n• Kolaborasi Kreatif Murid DKV: Mengarahkan murid kelas X-B DKV dan X-C DKV untuk mengubah hasil perhitungan statistik deskriptif di Excel menjadi infografis kampanye hemat air dan keselamatan ekosistem sungai menggunakan perangkat lunak grafis.\n• Mengasah Penalaran Kritis Berbasis Lingkungan: Mengajak murid menelaah korelasi antara alih fungsi lahan gambut dengan ancaman banjir rob musiman di Banjarmasin melalui representasi grafik komputasi."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran pendukung inovasi ini antara lain:\n• Modul Ajar TIK Berbasis TPACK & Konteks Lahan Basah (Tugas Aksi Nyata Topik 2/3): Modul ajar yang mengkaji integrasi aplikasi perkantoran dengan studi kasus data hidrologi Waduk Riam Kanan Kalimantan Selatan.\n• Dataset Praktikum Simulasi Waduk Riam Kanan (12 Bulan): Lembar kerja data autentik yang disiapkan guru untuk aktivitas pengolahan formula dan grafik spreadsheet murid.\n• Laporan Hasil Analisis Karakteristik Lingkungan & Peta Inovasi Media Pembelajaran Lahan Basah: Dokumen telaah kurikulum muatan lokal ULM pada rumpun kejuruan teknologi informasi."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena membuktikan orisinalitas dan kekhasan kontekstual rancangan pembelajaran saya. Mengaitkan praktikum komputer dengan isu Waduk Riam Kanan membuktikan bahwa teknologi komputasi dapat membumi dan membangkitkan rasa memiliki (sense of belonging) murid terhadap kelestarian daerahnya."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Modul Ajar TIK Bagian Bahan Ajar Praktikum, tercantum narasi studi kasus: 'Analisis Fluktuasi Debit Air Waduk Riam Kanan untuk Ketahanan Energi dan Ekosistem Banjar'. Lembar kerja ini memandu murid melakukan validasi data ekstrem (musim kemarau vs hujan), membuat formula statistik (`AVERAGE`, `MAX`, `MIN`), serta menyusun grafik batang-garis yang merefleksikan dinamika lahan basah."}]}, "sem2-pma-lanjut": {"title": "LEMBAR KERJA 2 (LK 2) — PEMBELAJARAN MENDALAM DAN ASESMEN LANJUT", "filename": "LK Refleksi Semester 2 Pembelajaran Mendalam dan Asesmen Lanjut _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 2 Pembelajaran Mendalam dan Asesmen Lanjut _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini merupakan penguatan lanjutan yang sangat krusial dalam menyempurnakan strategi pedagogik inklusif di sekolah kejuruan. Menghadapi kelas X-B DKV dan X-C DKV di SMKN 1 Banjarmasin dengan variasi kesiapan belajar yang mencolok menuntut guru untuk menguasai sintesis tiga pilar utama: Desain Universal untuk Pembelajaran (DUP / UDL), Teaching at the Right Level (TaRL), dan Culturally Responsive Teaching (CRT).\nPerkuliahan ini membekali saya kemampuan menganalisis data asesmen awal secara presisi, lalu merumuskan intervensi pembelajaran yang memastikan setiap anak, baik yang tertinggal maupun yang berakselerasi tinggi, mendapatkan hak belajar yang bermakna dan berkeadilan."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan intelektual terbesar bagi saya adalah bagaimana menyatukan ketiga kerangka kerja (DUP, TaRL, dan CRT) ke dalam satu modul ajar yang aplikatif, operasional, dan tidak membingungkan saat diterapkan di laboratorium komputer dalam batas waktu 3 JP.\nSebelumnya, penanganan murid yang lambat sering kali hanya berupa 'menambah waktu di akhir jam' atau sekadar meminta teman sebangkunya mengerjakan tugasnya. Mata kuliah ini mendobrak kebiasaan tersebut: intervensi harus direncanakan sejak awal melalui diferensiasi konten media, pengelompokan tingkat kemahiran yang cair, dan perancangan tugas berbasis konteks kultural yang relevan bagi murid."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep mutakhir yang saya kuasai meliputi:\n• Desain Universal untuk Pembelajaran (DUP / UDL): 3 prinsip utama: menyediakan beragam cara keterlibatan (multiple means of engagement), beragam cara representasi materi (representation), serta beragam cara aksi dan ekspresi hasil belajar (action & expression).\n• Teaching at the Right Level (TaRL): Mengelompokkan murid secara fleksibel berdasarkan tingkat kesiapan aktual hasil asesmen diagnostik (kategori: Perintis, Cakap, dan Mahir), bukan berdasarkan usia atau tingkatan kelas kaku.\n• Culturally Responsive Teaching (CRT): Mengintegrasikan narasi budaya, realitas sosiogeografis lahan basah, dan kearifan lokal Kalimantan Selatan ke dalam tema studi kasus analisis data komputasi.\n• Analisis Data Asesmen Berbasis Empati & N-Gain Ternormalisasi: Mengukur efektivitas intervensi pengajaran melalui penghitungan lonjakan gain skor dari pre-test ke post-test."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Langkah transformasi nyata yang saya wujudkan di SMKN 1 Banjarmasin meliputi:\n• Menerapkan DUP dalam Penyediaan Bahan Ajar: Menyediakan materi dalam tiga modalitas: modul teks terstruktur bergambar, video tutorial demonstrasi ringkas di YouTube/LMS, dan demonstrasi langsung di proyektor lab.\n• Mengimplementasikan TaRL pada Praktikum Pengolahan Data: Di kelas X-B DKV (35 murid), membagi kelas menjadi kelompok Perintis (didampingi modul bertahap), Cakap (tugas analisis mandiri), dan Mahir (diberi tantangan formula lanjutan serta difungsikan sebagai konsultan sebaya).\n• Evaluasi Berbasis Data Empiris: Menghitung N-Gain hasil belajar kelas X-B DKV di mana rata-rata nilai melonjak dari 52.3 (Pre-Test) menjadi 83.3 (Post-Test) dengan ketuntasan 100% dan efektivitas sedang-tinggi."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran komprehensif yang mendukung refleksi ini terdiri atas:\n• Modul Ajar TIK Terintegrasi DUP, TaRL, dan CRT: Modul ajar Fase E materi Analisis Data dan Pemanfaatan Aplikasi Perkantoran di SMKN 1 Banjarmasin.\n• Laporan Hasil Analisis Pre-Test & Post-Test Kelas X-B DKV (Berkas Excel): Dokumen rekapitulasi data 35 murid yang memuat sebaran kategori awal TaRL (Perintis, Cakap, Mahir), nilai sumatif, selisih poin, dan formula N-Gain ternormalisasi.\n• Laporan Best Practice Ujian Akhir Semester: Dokumen sintesis penerapan intervensi inklusif dan evaluasi keberhasilan belajar murid kejuruan."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak ini saya pilih karena menyajikan data kuantitatif dan kualitatif paling valid atas unjuk kerja pedagogik saya. Laporan analisis asesmen pre-post test membuktikan bahwa penerapan TaRL dan DUP yang saya rancang secara nyata berhasil mengangkat kemampuan murid kelompok Perintis (dari nilai 30-40 melonjak mencapai batas tuntas 70-80)."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada berkas Excel lembar 'Ringkasan Eksekutif' dan 'Data Hasil Pre-Post Test', tercantum data faktual 35 murid kelas X-B DKV: nilai minimum naik dari 30 menjadi 70 (+40 poin), nilai rata-rata naik +31 poin, serta kolom N-Gain yang menunjukkan mayoritas murid mencapai kriteria efektivitas tinggi. Hal ini membuktikan keberhasilan diferensiasi bimbingan praktikum di lab."}]}, "sem2-pse": {"title": "LEMBAR KERJA 2 (LK 2) — PEMBELAJARAN SOSIAL EMOSIONAL (PSE)", "filename": "LK Refleksi Semester 2 Pembelajaran Sosial Emosional _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 2 Pembelajaran Sosial Emosional _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini menyadarkan saya bahwa keberhasilan akademik dan keterampilan teknis murid SMK dalam bidang Informatika berakar kuat pada kematangan sosial-emosional mereka. Di SMKN 1 Banjarmasin, proses belajar di depan komputer sering kali memicu tekanan emosional terselubung: kecemasan saat tugas tidak kunjung selesai, frustrasi saat data tidak valid, hingga friksi antarteman saat kerja kelompok proyek.\nSebagai guru, saya tidak bisa hanya berfungsi sebagai instruktur perangkat keras dan lunak. Saya harus hadir sebagai fasilitator yang membimbing murid mengelola emosi, membangun empati, dan mengambil keputusan yang bertanggung jawab di dunia nyata maupun ruang digital."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan utama yang mendobrak kebiasaan saya adalah anggapan bahwa kelas Informatika itu murni dunia logika rasional yang tidak membutuhkan sentuhan emosional. Saya sempat berpikir bahwa waktu 120 menit di lab sudah sangat padat untuk mengejar materi praktikum, sehingga tidak ada ruang untuk aktivitas refleksi atau regulasi diri.\nMata kuliah ini membuktikan kebalikannya: murid yang kondisi emosinya tegang atau merasa tidak aman secara psikologis akan mengalami penyempitan kapasitas kognitif (amigdala membajak prefrontal korteks). Mengintegrasikan Pembelajaran Sosial Emosional (PSE) justru mempercepat pemahaman materi karena murid belajar dalam kondisi batin yang tenang, fokus, dan siap menerima tantangan."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep inti yang saya kuasai dan terapkan meliputi:\n• 5 Kompetensi Sosial Emosional (KSE CASEL): Kesadaran Diri (Self-Awareness), Manajemen Diri (Self-Management), Kesadaran Sosial (Social Awareness), Keterampilan Berelasi (Relationship Skills), dan Pengambilan Keputusan Bertanggung Jawab (Responsible Decision-Making).\n• Teknik STOP untuk Mindfulness: Stop (berhenti sejenak), Take a breath (tarik napas dalam), Observe (amati sensasi tubuh dan emosi), dan Proceed (lanjutkan aktivitas dengan kesadaran penuh).\n• Teori Experiential Learning David Kolb: Siklus belajar melalui pengalaman konkret, observasi reflektif, konseptualisasi abstrak, dan eksperimentasi aktif.\n• Kesejahteraan Sekolah (School Well-Being): Menciptakan iklim kelas yang aman, bebas perundungan siber (cyberbullying), serta penuh rasa saling menghargai."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Langkah perbaikan nyata yang saya implementasikan di kelas X-B DKV dan X-C DKV adalah:\n• Menerapkan Teknik STOP Secara Terjadwal: Memandu jeda hening dan pernapasan berkesadaran (3 menit) di pertengahan sesi praktikum saat murid mulai menunjukkan tanda-tanda jenuh dan lelah menatap layar.\n• Menyusun Penugasan Kelompok Berbasis Keterampilan Berelasi: Membagi peran yang jelas dalam kelompok proyek (seperti Ketua Analis, Desainer Visual, dan Verifikator Data) sehingga setiap murid merasa memiliki kontribusi berharga.\n• Membangun Budaya Refleksi Emosi: Menyediakan papan stiker emosi (mood meter) di pintu masuk kelas/lab untuk memantau kesiapan mental murid sebelum pembelajaran dimulai."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran pendukung yang saya pilih antara lain:\n• Modul Ajar TIK Terintegrasi 5 KSE CASEL & Teknik STOP: Rencana pembelajaran Informatika Fase E yang memuat integrasi eksplisit langkah-langkah kesadaran penuh pada kegiatan inti.\n• Lembar Refleksi Diri 'Guru Sebagai Teladan Emosi' (Tugas LK 2.1 & LK 2.E): Berkas evaluasi kemampuan guru mengelola emosi pribadi saat menghadapi dinamika ketidaktertiban kelas.\n• Lembar Observasi Respons Murid terhadap Relaksasi Mindfulness: Catatan perubahan fokus dan ketenangan murid X-B DKV pasca-penerapan teknik STOP di laboratorium komputer."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak ini saya pilih karena menunjukkan integrasi yang harmonis antara kecakapan digital dengan pembinaan karakter batin. Modul Ajar terintegrasi KSE menjadi bukti bahwa saya mampu merancang kegiatan TIK yang tidak kering dari nilai kemanusiaan dan kepedulian mental murid."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Modul Ajar bagian Kegiatan Inti (fase peralihan sebelum pengerjaan proyek), tercantum panduan verbal guru dalam memandu teknik STOP: 'Anak-anak sekalian, lepaskan tangan dari tetikus (mouse), tegakkan punggung, pejamkan mata sejenak, dan rasakan napas kalian...'. Kalimat ini terbukti berhasil meredakan ketegangan murid saat menghadapi kerumitan pengolahan data."}]}, "sem2-ppl-mandiri": {"title": "LEMBAR KERJA 2 (LK 2) — PRAKTIK PENGALAMAN LAPANGAN (PPL) MANDIRI", "filename": "LK Refleksi Semester 2 Praktik Pengalaman Lapangan Mandiri _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 2 Praktik Pengalaman Lapangan Mandiri _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "PPL Mandiri di SMKN 1 Banjarmasin merupakan tahap puncak pembuktian kematangan profesional saya sebagai guru Informatika seutuhnya. Berbeda dengan PPL Terbimbing yang masih didampingi intensif oleh Guru Pamong di dalam ruangan, pada PPL Mandiri saya memegang kendali penuh 100% jam tatap muka di kelas X-B DKV dan X-C DKV.\nMata kuliah ini menuntut kemandirian pedagogik, kestabilan emosi, kecepatan pengambilan keputusan di tempat (in-situ decision making), serta kemampuan beradaptasi dengan ritme kehidupan sekolah kejuruan yang dinamis."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan kemandirian yang menguji kapasitas profesional saya di lapangan meliputi:\n• Kemandirian Mengajar Penuh: Mengelola dinamika 35 murid di laboratorium komputer sendirian, memastikan keselamatan peralatan, menegakkan disiplin lab, serta mengawal seluruh tahapan pembelajaran tuntas tepat waktu.\n• Mengatasi Kejenuhan dan Pasivitas Murid: Mempertahankan energi dan fokus murid DKV yang mudah bosan jika pembelajaran berlangsung monoton, melalui variasi ice breaking dan tantangan kuis interaktif.\n• Penyelesaian Masalah Teknis Mandiri: Menangani insiden teknis di laboratorium komputer (komputer murid mendadak mati, kabel jaringan bermasalah, atau proyektor tidak merespons) secara taktis tanpa membuat kegaduhan di kelas."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep esensial yang terasah kokoh selama PPL Mandiri meliputi:\n• Autonomous Professional Teaching: Kematangan dalam mengambil keputusan instruksional secara mandiri, bertanggung jawab, dan selaras dengan kode etik guru profesional.\n• Praktisi yang Reflektif (Donald Schön - Reflective Practitioner): Pembiasaan melakukan Reflection-in-Action (berpikir cepat mengubah strategi saat proses mengajar sedang berjalan) dan Reflection-on-Action (mengevaluasi pembelajaran setelah kelas usai).\n• Continuous Formative Monitoring: Pengawasan formatif yang mengalir natural tanpa membuat murid merasa dihakimi atau tertekan.\n• Integrasi Budaya Sekolah (School Culture Integration): Keterlibatan aktif dalam pembiasaan positif sekolah (piket pagi, menyambut murid dengan salam senyum sapa, upacara bendera, dan koordinasi antarguru)."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Transformasi kepribadian dan keterampilan profesional yang melekat pada diri saya adalah:\n• Memiliki Ketahanan Mental dan Ketegasan yang Humanis: Mampu mengendalikan kelas laboratorium dengan pendekatan apresiatif tanpa perlu menggunakan nada suara tinggi atau hukuman yang mempermalukan murid.\n• Disiplin Menulis Jurnal Refleksi Harian: Menuangkan evaluasi diri setiap kali bel pelajaran berbunyi, mendokumentasikan apa yang berhasil dan hal teknis apa yang perlu diperbaiki besok.\n• Kesiapan Menghadapi Kejutan Teknis: Memiliki protokol antisipasi masalah di lab (misal selalu menyiapkan fail materi cadangan di flashdisk dan lembar kerja offline bila server sekolah mengalami maintenance)."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran otentik yang mendukung refleksi PPL Mandiri antara lain:\n• Laporan Portofolio Mengajar Mandiri PPL SMKN 1 Banjarmasin: Dokumen lengkap modul ajar mandiri, lembar asesmen diagnostik dan sumatif, serta rekapitulasi nilai kelas X-B DKV dan X-C DKV.\n• Buku Jurnal Refleksi Harian Guru PPL Mandiri: Catatan reflektif harian mengenai kendala manajemen kelas, respons belajar murid, dan solusi taktis yang diambil.\n• Lembar Penilaian Kinerja Mengajar Mandiri dari Guru Pamong dan Kepala Sekolah: Bukti evaluasi formal atas integritas, kedisiplinan, dan kompetensi mengajar mandiri."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena merekam kemandirian dan integritas unjuk kerja saya di dunia pendidikan nyata. Jurnal refleksi harian dan berkas portofolio mengajar mandiri membuktikan bahwa saya mampu mengemban tanggung jawab penuh seorang pendidik profesional di sekolah kejuruan."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Jurnal Refleksi Harian catatan pertemuan ke-8, tertulis kronologi saat koneksi internet sekolah sempat terputus saat murid sedang mengumpulkan berkas praktikum secara daring. Dokumen mencatat keputusan cepat saya mengalihkan pengumpulan melalui jaringan lokal ad-hoc LAN dan pemeriksaan langsung di layar murid, sehingga 35 murid tetap tenang dan jam pelajaran tuntas tanpa waktu yang terbuang."}]}, "sem2-kepemimpinan": {"title": "LEMBAR KERJA 2 (LK 2) — PROJEK KEPEMIMPINAN", "filename": "LK Refleksi Semester 2 Projek Kepemimpinan _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 2 Projek Kepemimpinan _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah ini memperluas horizon keprofesian saya: seorang guru tidak boleh hanya membatasi perannya di dalam dinding ruang kelas atau bilik laboratorium komputer, melainkan harus bertindak sebagai pemimpin pembelajaran (learning leader) dan agen perubahan (change agent) yang mampu menggerakkan ekosistem sekolah dan masyarakat sekitar.\nDi era disrupsi digital, sekolah menghadapi berbagai tantangan literasi, etika media sosial, dan kecerdasan buatan. Mata kuliah ini menghubungkan kompetensi teknis Informatika saya dengan kepemimpinan transformasional untuk merancang inisiatif sosial-pendidikan yang memberikan dampak maslahat berkelanjutan."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan terbesar dalam perkuliahan ini adalah mengelola dinamika kolaborasi kelompok mahasiswa lintas latar belakang dan menyelaraskan beragam ide menjadi satu rencana aksi yang realistis. Sebelumnya, sebagai lulusan ilmu komputer, saya terbiasa bekerja mandiri menyelesaikan proyek teknis individual di depan layar.\nMata kuliah ini menantang saya untuk keluar dari zona nyaman: membangun komunikasi dengan pemangku kepentingan sekolah mitra, menyusun proposal berbasis kerangka kerja SMART, mengelola anggaran dan linimasa yang ketat, serta mengeksekusi program di tengah padatnya jadwal PPL di sekolah."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep kepemimpinan esensial yang saya internalisasikan meliputi:\n• Visi Guru Profesional & Servant Leadership: Kepemimpinan yang melayani dengan menempatkan kebutuhan komunitas murid dan rekan sejawat sebagai prioritas utama.\n• Kerangka Kerja BAGJA (Inkuiri Apresiatif): Tahapan Buat pertanyaan utama, Ambil pelajaran, Gali mimpi, Jabarkan rencana, dan Atur eksekusi berbasis aset positif yang ada, bukan meratapi kekurangan.\n• Prinsip SMART Goals: Perumusan target proyek yang Specific (jelas), Measurable (terukur indikatornya), Achievable (dapat dicapai), Relevant (relevan dengan kebutuhan), dan Time-bound (berbatas waktu tegas).\n• Sustainable Development Goals (SDGs 4 - Pendidikan Berkualitas): Penyelarasan inisiatif proyek dengan agenda peningkatan mutu dan pemerataan literasi digital."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Komitmen perubahan yang saya bawa dalam karier sebagai pendidik adalah:\n• Aktif Menginisiasi Program Peningkatan Mutu Sekolah: Tidak pasif menunggu instruksi pimpinan, melainkan proaktif mengusulkan workshop literasi digital dan pemanfaatan AI yang etis bagi murid dan rekan guru di sekolah.\n• Membangun Kolaborasi Berbasis Kekuatan Aset: Menerapkan pola pikir inkuiri apresiatif dalam memecahkan hambatan sekolah, memaksimalkan aset laboratorium dan potensi kreatif murid kejuruan.\n• Menjaga Keberlanjutan Program (Sustainability): Merancang setiap inisiatif agar memiliki sistem kaderisasi dan dokumentasi SOP yang rapi sehingga dapat terus berjalan mandiri."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran pendukung yang relevan terdiri atas:\n• Proposal Final Projek Kepemimpinan & Bahan Presentasi UTS (SMART Goals & Timeline): Dokumen perencanaan inisiatif workshop literasi digital dan keamanan siber bagi murid kejuruan.\n• Laporan Akhir Pelaksanaan Projek Kepemimpinan (Tugas 10.1): Berkas evaluasi pelaksanaan proyek kolaboratif kelompok yang memuat dokumentasi kegiatan, realisasi anggaran, dan analisis umpan balik peserta.\n• Dokumen Rencana Keberlanjutan (Sustainability Plan) & Lembar Kerja BAGJA (LK 1.13): Peta jalan serah terima program kepada pihak mitra pengelola di sekolah."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena membuktikan kapasitas kepemimpinan manajerial dan sosial saya di luar kelas. Proposal dan laporan akhir proyek menjadi bukti konkret bahwa saya mampu merancang ide perubahan, mengorganisasi sumber daya manusia, dan mewujudkan program pendidikan yang berdampak nyata."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Laporan Akhir Projek Kepemimpinan Bagian 'Evaluasi Dampak dan Refleksi Komunitas (LK 1.13)', tercantum hasil survei kepuasan peserta workshop di mana 92% murid menyatakan meningkatnya kesadaran menjaga keamanan data pribadi di internet. Bagian ini membuktikan tercapainya indikator terukur (measurable) yang telah ditetapkan dalam kerangka SMART."}]}, "sem2-seminar-ppg": {"title": "LEMBAR KERJA 2 (LK 2) — SEMINAR PENDIDIKAN PROFESI GURU", "filename": "LK Refleksi Semester 2 Seminar Pendidikan Profesi Guru _ A. Wahyu Redhani _ 2530111713968.pdf", "pdf": "LK Refleksi Semester 2 Seminar Pendidikan Profesi Guru _ A. Wahyu Redhani _ 2530111713968.pdf", "rows": [{"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "1. Apa keterkaitan materi perkuliahan dengan peran saya sebagai calon guru?", "jawaban": "Mata kuliah Seminar PPG merupakan ruang puncak metakognitif yang menyintesiskan seluruh rekam jejak perjalanan belajar saya selama menempuh Program PPG Calon Guru Informatika di Universitas Lambung Mangkurat. Mata kuliah ini mempertemukan seluruh untaian teori perkuliahan semester 1 dan 2 dengan realitas praktik lapangan di SMKN 1 Banjarmasin ke dalam satu kesatuan Portofolio Digital yang bermakna.\nBagi calon guru, mata kuliah ini menegaskan kembali jati diri dan komitmen profesi: bahwa guru bukan sekadar pencari nafkah teknis, melainkan arsitek peradaban yang secara berkesadaran terus memperbarui diri demi memuliakan murid-muridnya."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "2. Apa saja materi perkuliahan yang berbeda dari praktik yang saya lakukan selama ini?", "jawaban": "Tantangan terbesar dalam mata kuliah ini adalah melakukan evaluasi diri (self-assessment) dan metakognisi secara jujur tanpa bersikap defensif. Mengakui kelemahan diri di masa lalu, seperti kecenderungan mengajar seragam, kurang sabar menghadapi murid lambat, atau kurang matang dalam manajemen waktu lab, memerlukan kerendahan hati profesional.\nSelain itu, tantangan berikutnya adalah mengkurasi artefak-artefak terbaik dari 12 mata kuliah yang telah dijalani, serta merumuskan Desain Karya Inovatif pendidikan yang teruji, memiliki kebaruan, relevan dengan Kurikulum Merdeka, dan benar-benar menjawab kebutuhan riil murid di sekolah kejuruan."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "3. Apa saja konsep utama dan penting yang telah saya pelajari sebagai calon guru?", "jawaban": "Konsep-konsep esensial yang menjadi mahkota keilmuan saya meliputi:\n• Metakognisi Reflektif (Model 4C): Kerangka evaluasi Connection (keterkaitan materi dengan peran guru), Challenge (perbedaan dengan praktik masa lalu), Concept (konsep-konsep kunci yang dipelajari), dan Change (rencana perubahan konkret pada praktik mengajar).\n• Portofolio Digital Berbasis Artefak Bermakna: Dokumentasi unjuk kerja digital yang tersusun sistematis sebagai bukti pertumbuhan kompetensi guru profesional.\n• 5 Prinsip Karya Inovasi Pendidikan: Kriteria mutlak karya inovasi yang mencakup Kebaruan (Novelty), Kreativitas, Kebermanfaatan (Usefulness), Relevansi dan Kontekstualitas, serta Efektivitas Terbukti (Evidence-Based).\n• Rencana Pengembangan Keprofesian Berkelanjutan (PKB): Peta jalan pengembangan karir guru pembelajar sepanjang hayat (lifelong learner)."}, {"indikator": "Refleksi pengalaman belajar dalam konteks sebagai calon guru (connection, challenge, concept, change).", "pertanyaan": "4. Apa saja perubahan yang ingin saya lakukan setelah mendapatkan materi perkuliahan ini?", "jawaban": "Komitmen jangka panjang yang saya tetapkan dalam memasuki dunia pengabdian guru adalah:\n• Konsisten Mengembangkan Inovasi Media Digital: Terus menyempurnakan platform website Informatika Learning Hub sebagai media pembelajaran mandiri interaktif bagi murid SMK.\n• Menjadikan Refleksi Sebagai Nafas Harian Mengajar: Menulis jurnal evaluasi berkala dan terbuka menerima umpan balik rekan sejawat melalui kegiatan Lesson Study dan Komunitas Belajar (MGMP).\n• Melakukan Penelitian Tindakan Kelas (PTK): Mengkaji dan meneliti secara ilmiah efektivitas berbagai metode pembelajaran inovatif guna memecahkan kesulitan belajar murid di laboratorium komputer."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "1. Mana saja artefak pembelajaran yang dapat saya jadikan bukti dukung hasil refleksi pengalaman belajar ini?", "jawaban": "Artefak pembelajaran puncak yang menjadi bukti dukung refleksi ini adalah:\n• Tautan Portofolio Digital PPG Informatika: Repositori daring yang mengompilasi refleksi model 4C beserta dokumen artefak otentik dari 12 mata kuliah yang telah diselesaikan.\n• Dokumen Desain Karya Inovatif (LK 4 - Informatika Learning Hub): Rancangan komprehensif website pembelajaran interaktif Informatika berbasis web dengan prototipe materi Data, Informasi, dan Validasi.\n• Dokumen Refleksi Pengalaman Belajar Selama Mengikuti PPG (LK 3): Sintesis komprehensif pandangan tentang arah pendidikan Indonesia dan rencana tindak lanjut karier guru profesional."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "2. Mengapa artefak tersebut yang saya pilih?", "jawaban": "Artefak tersebut saya pilih karena merupakan muara sintesis (showcase) dari seluruh siklus pendidikan profesi yang saya tempuh. Dokumen Portofolio Digital, LK 3, dan Desain Karya Inovatif LK 4 membuktikan kesiapan paripurna saya secara pedagogik, profesional, sosial, dan kepribadian untuk mengabdi sebagai guru Informatika profesional."}, {"indikator": "Analisis artefak pembelajaran", "pertanyaan": "3. Bagian mana dari artefak ini yang mendukung hasil refleksi saya?", "jawaban": "Pada Portofolio Digital bagian 'Pameran Desain Karya Inovatif (LK 4)', terpapar secara rinci arsitektur website Informatika Learning Hub yang mengintegrasikan materi terstruktur, video tutorial, kuis interaktif, dan papan peringkat (leaderboard). Hal ini membuktikan bahwa perkuliahan Seminar PPG berhasil mendorong saya bertransformasi dari sekadar konsumen materi menjadi produsen inovasi pembelajaran yang berdaya guna."}]}};

function initTheme() {
  try {
    const saved = localStorage.getItem('wahyu_ppg_theme');
    if (saved === 'dark') {
      document.documentElement.classList.add('dark');
    } else if (saved === 'light') {
      document.documentElement.classList.remove('dark');
    }
  } catch (e) {}
  updateThemeButtonLabel();
}

function toggleTheme() {
  const isDark = document.documentElement.classList.toggle('dark');
  try {
    localStorage.setItem('wahyu_ppg_theme', isDark ? 'dark' : 'light');
  } catch (e) {}
  updateThemeButtonLabel();
}

function updateThemeButtonLabel() {
  const isDark = document.documentElement.classList.contains('dark');
  const iconEl = document.getElementById('theme-icon');
  const textEl = document.getElementById('theme-text');
  if (iconEl) iconEl.textContent = isDark ? '☀️' : '🌙';
  if (textEl) textEl.textContent = isDark ? 'Light Mode' : 'Dark Mode';
}

function toggleMobileMenu() {
  const menu = document.getElementById('mobile-nav-menu');
  if (menu) menu.classList.toggle('hidden');
}

function openLkModal(key) {
  const item = LK_DATABASE[key];
  if (!item) return;
  const modal = document.getElementById('lk-viewer-modal');
  const titleEl = document.getElementById('lk-modal-title');
  const fileEl = document.getElementById('lk-modal-filename');
  const bodyEl = document.getElementById('lk-modal-body');
  const actionsEl = document.getElementById('lk-modal-actions');

  if (titleEl) titleEl.textContent = item.title;
  if (fileEl) fileEl.textContent = 'Nama File: ' + item.filename;

  let rowsHtml = '<div class="overflow-x-auto"><table class="w-full text-left border-collapse text-sm">';
  rowsHtml += '<thead><tr class="bg-slate-900 text-white"><th class="p-3.5 border border-slate-700 w-1/5">Indikator</th><th class="p-3.5 border border-slate-700 w-1/4">Pertanyaan Pemantik</th><th class="p-3.5 border border-slate-700">Uraian Jawaban Lengkap Mahasiswa</th></tr></thead><tbody>';

  item.rows.forEach((r, idx) => {
    const bgClass = idx % 2 === 0 ? 'surface-card' : 'surface-subtle';
    const formattedAns = (r.jawaban || '').split('\n').map(p => `<p class="mb-2 leading-relaxed">${p}</p>`).join('');
    rowsHtml += `<tr class="${bgClass} align-top">
      <td class="p-3.5 border border-slate-300 dark:border-slate-700 font-bold text-blue-600 dark:text-blue-400 text-xs">${r.indikator || ''}</td>
      <td class="p-3.5 border border-slate-300 dark:border-slate-700 font-semibold text-xs">${r.pertanyaan || ''}</td>
      <td class="p-3.5 border border-slate-300 dark:border-slate-700 text-xs sm:text-sm">${formattedAns}</td>
    </tr>`;
  });
  rowsHtml += '</tbody></table></div>';

  // Also include embedded PDF object viewer for GitHub Pages deployment
  rowsHtml += `<div class="mt-6 p-4 rounded-xl surface-subtle border border-blue-500/30">
    <div class="flex flex-wrap items-center justify-between gap-2 mb-3">
      <span class="text-xs font-bold uppercase tracking-wider text-blue-600 dark:text-blue-400">📄 Pratinjau PDF Langsung (GitHub Pages / Browser PDF Viewer)</span>
      <a href="lk/${encodeURIComponent(item.pdf)}" target="_blank" rel="noopener" onclick="handleDownloadLk(event, '${item.pdf}', '${key}')" class="text-xs font-bold text-blue-600 dark:text-blue-400 underline">Buka PDF di Tab Baru ↗</a>
    </div>
    <p class="text-xs opacity-75">Saat di-publish di GitHub Pages, file <code>lk/${item.pdf}</code> dan <code>lk/${item.filename}</code> berada di dalam folder <code>/lk/</code> sehingga dapat dilihat (View) maupun diunduh (Download) langsung oleh pengunjung.</p>
  </div>`;

  if (bodyEl) bodyEl.innerHTML = rowsHtml;

  let actHtml = '';
  if (item.pdf) {
    actHtml += `<a href="lk/${encodeURIComponent(item.pdf)}" download="${item.pdf}" onclick="handleDownloadLk(event, '${item.pdf}', '${key}')" class="px-4 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold transition">⬇️ Download PDF (.pdf)</a>`;
  }
  actHtml += `<button type="button" onclick="window.print()" class="px-4 py-2 rounded-xl surface-subtle hover:border-blue-500 text-xs font-bold transition">🖨️ Cetak / Simpan sebagai PDF</button>`;
  if (actionsEl) actionsEl.innerHTML = actHtml;

  if (modal) modal.classList.remove('hidden');
}

function closeLkModal() {
  const modal = document.getElementById('lk-viewer-modal');
  if (modal) modal.classList.add('hidden');
}

function exportLkText(key) {
  const item = LK_DATABASE[key];
  if (!item) return;
  let htmlDoc = `<html><head><meta charset="utf-8"><title>${item.title}</title></head><body style="font-family:Calibri,sans-serif;padding:24px;">`;
  htmlDoc += `<h2>${item.title}</h2><p><strong>Nama Mahasiswa:</strong> Akhmad Wahyu Redhani | <strong>NIM:</strong> 2530111713968 | <strong>LPTK:</strong> Universitas Lambung Mangkurat (ULM)</p>`;
  htmlDoc += `<table border="1" cellspacing="0" cellpadding="8" style="border-collapse:collapse;width:100%;">`;
  htmlDoc += `<tr style="background:#1e3a8a;color:#fff;"><th>Indikator</th><th>Pertanyaan</th><th>Uraian Jawaban</th></tr>`;
  item.rows.forEach(r => {
    htmlDoc += `<tr><td><b>${r.indikator}</b></td><td>${r.pertanyaan}</td><td>${(r.jawaban || '').replace(/\n/g, '<br>')}</td></tr>`;
  });
  htmlDoc += `</table></body></html>`;
  const blob = new Blob([htmlDoc], { type: 'application/msword;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = item.filename.replace(/\.(docx|pdf)$/i, '') + '.doc';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('Berhasil mengunduh dokumen: ' + item.filename);
}

function handleDownloadLk(event, filename, key) {
  if (window.IS_CANVAS_PREVIEW) {
    event.preventDefault();
    openLkModal(key);
    showToast('Pratinjau PDF dibuka (pada GitHub Pages, tombol ini mengunduh file PDF: ' + filename + ')');
    return false;
  }
  showToast('Mengunduh file PDF: ' + filename);
  return true;
}

function openKaryaInovasiInfo(event) {
  if (window.IS_CANVAS_PREVIEW) {
    event.preventDefault();
    const modal = document.getElementById('karya-inovasi-redirect-modal');
    if (modal) modal.classList.remove('hidden');
    return false;
  }
  return true;
}

function closeKaryaInovasiInfo() {
  const modal = document.getElementById('karya-inovasi-redirect-modal');
  if (modal) modal.classList.add('hidden');
}

function showToast(msg) {
  const toast = document.getElementById('app-toast');
  const text = document.getElementById('app-toast-text');
  if (!toast || !text) return;
  text.textContent = msg;
  toast.classList.remove('hidden');
  clearTimeout(window._toastTimer);
  window._toastTimer = setTimeout(() => {
    toast.classList.add('hidden');
  }, 3500);
}

window.addEventListener('DOMContentLoaded', () => {
  initTheme();
});
